window.HADITH_BOOKS[10] = [{"id": 6335, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 1, "arabic": "عَنْ عُمَرَ ابْنِ الْخَطَّابِ رَضِیَ اللّٰہُ تَعَالٰی عَنْہُ قَالَ: قَالَ: رَسُوْلُ اللّٰہِ صَلَّی اللّٰہُ عَلَیْہِ وَسَلَّمَ اِنَّمَا الْاَعْمَالُ بِالنِّیَّاتِ وَاِنَّمَا لِامْرِیٍٔ مَّا نَویٰ فَمَنْ کَانَتْ ہِجْرَتُہٗ اِلَی اللّٰہِ وَرَسُوْلِہٖ فَھِجْرَتُہٗ اِلَی اللّٰہ وَرَسُوْلِہٖ وَمَنْ کَانَتْ ہِجْرَتُہٗ اِلَی دُنْیَا یُصِیْبُھَا اَوِامْرَأَۃٍ یَّتَزَوَّجُھَا فَھِجْرَتُہٗ اِلٰی مَا ھَاجَرَ اِلَیْہِ۔ (صحیح البخاری،کتاب بدء الوحی، باب کیف کان بدء الوحی الی رسول اللّٰہ صلی اللّٰہ تعالیٰ علیہ وسلم، الحدیث:۱، ج۱، ص۵, وصحیح مسلم،کتاب الامارۃ،باب قولہصلی اللّٰہ تعالیٰ علیہ وسلم:انما الاعمال۔۔۔الخ، الحدیث:۱۹۰۷، ص۱۰۵۶)", "urdu": "حضرت عمر بن خطاب رضی اللّٰہ تعالیٰ عنہ سے روایت ہے انہوں نے کہا کہ رسول اللّٰہ عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا کہ تمام اعمال کا ثواب نیتوں سے ہے اور ہر آدمی کے لئے وہی ہے جو اس نے نیت کی ۔ جس شخص کی ہجرت اللّٰہ اور اس کے رسول کی طرف ہوتو اس کی ہجرت اللّٰہ اور اس کے رسول کے لئے ہے اور جس شخص کی ہجر ت دنیا حاصل کرنے کے لئے یا کسی عورت سے نکاح کے واسطے ہوتو اس کی ہجرت اسی کے لئے ہوگی جس کی طرف اس نے ہجرت کی ہے ۔", "roman": "Hazrat Umar bin Khattab Radiyallahu Ta'ala Anhu se Riwayat hai unhon ne kaha ke Rasoolullah Azza wa Jall wa Sallallahu Ta'ala Alaihi wa Aalihi wa Sallam ne farmaya ke tamam aamaal ka sawaab niyyaton se hai aur har aadmi ke liye wahi hai jo us ne niyyat ki. Jis Shakhs ki hijrat Allah aur us ke Rasool ki taraf ho to us ki hijrat Allah aur us ke Rasool ke liye hai aur jis Shakhs ki hijrat dunya haasil karne ke liye ya kisi Aurat se Nikah ke waaste ho to us ki hijrat usi ke liye hogi jis ki taraf us ne hijrat ki hai."}, {"id": 6336, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 2, "arabic": "عَنْ اَبِیْ ہُرَیْرَۃَ قَالَ:کَانَ النَّبِیُّ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰٰلِہٖ وَسَلَّمَ بَارِزًا یومًا لِلنَّاسِ فَاَتَاہُ رَجُلٌ فَقَالَ:مَا الْاِیْمَانُ؟ قَالَ:اَلْاِیْمَانُ اَنْ تُؤْمِنَ بِاللّٰہ وَمَلٰئِکَتِہٖ وَبِلِقَائِہٖ وَرُسُلِہٖ وَتُؤْمِنَ بِالْبَعْثِ قَالَ:مَا الْاِسْلَامُ؟ قَالَ:اَلْاِسْلَامُ اَنْ تَعْبُدَ اللّٰہ وَلَا تُشْرِکَ بِہٖ وَتُقِیْمَ الصَّلَاۃَ وَتُؤَدِّیَ الزَّکَاۃَ الْمَفْرُوْضَۃَ وَتَصُوْمَ رَمَضَانَ قاَلَ: مَا الْاِحْسَانُ؟ قَالَ: اَنْ تَعْبُدَ اللّٰہ کَاَنَّکَ تَرَاہُ فَاِنْ لَّمْ تَکُنْ تَرَاہُ فَاِنَّہٗ یَرَاکَ قَالَ: مَتٰی السَّاعَۃُ؟ قَالَ:مَا الْمَسْئُوْلُ عَنْہَا بِاَعْلَمَ مِنَ السَّائِلِ وَسَاُخْبِرُکَ عَنْ اَشْرَاطِھَا اِذَا وَلَدَتِ الْاَمَۃُ رَبَّھَا وَاِذَا تَطَاوَلَ رُعَاۃُ الْاِبِلِ الْبُھْمُ فِی الْبُنْیَانِ فِیْ خَمْسٍ لَا یَعْلَمُھُنَّ اِلَّا اللّٰہ ثُمَّ تَلَا النَّبِیُّ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَسَلَّمَ:اِنَّ اللّٰہ عِنْدَہٗ عِلْمُ السَّاعَۃِ اَلْاٰیَۃُ، ثُمَّ اَدْبَرَ فَقَالَ: رُدُّوْہُ فَلَمْ یَرَوْا شَیْئًا فَقَالَ:ھٰذَا جِبْرِیْلُ جَائَ یُعَلِّمُ النَّاسَ دِیْنَھُمْ۔ (صحیح البخاری،کتاب الایمان،باب سؤال جبریل۔۔۔الخ،الحدیث:۵۰،ج۱،ص۳۱)", "urdu": "حضرت ابو ہریرہ رضی اللّٰہ تعالیٰ عنہ سے روایت ہے انہوں نے کہا کہ ایک دن حضور نبی کریم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم لوگوں سے ملاقات کے لئے مکان سے باہر تشریف فرما تھے تو ایک آدمی آیا اور اس نے کہا کہ ایمان کیا ہے ؟ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا کہ ایمان یہ ہے کہ اللّٰہ کو اور اس کے فرشتوں کو اور اس کی ملاقات کو اور اس کے رسولوں کو اور موت کے بعد اُٹھنے کو تو دل سے مان لے ۔اس نے کہا: اسلام کیا ہے ؟ تو حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا کہ اسلام یہ ہے کہ تو خاص اللّٰہ تعالیٰ ہی کی عبادت کرے اور کسی کو اس کا شریک نہ ٹھہرائے اور نماز قائم کرے اور زکوٰۃ دے جو فرض ہے اور رمضان کے روزے رکھے ۔ اس نے کہاکہ احسان کیا ہے ؟تو حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا کہ احسان یہ ہے کہ تو اللّٰہ کی عبادت اس طرح کرے گویا کہ تو اللّٰہ تعالیٰ کو دیکھ رہا ہے پس اگر تو اس کو نہیں دیکھتاتو (اس طرح عبادت کرکہ ) وہ تجھ کو دیکھ رہا ہے۔ پھر اس نے کہا کہ قیامت کب آئے گی ؟ تو حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا کہ جس سے سوال کیا گیا ہے وہ سوال کرنے والے سے زیادہ نہیں جانتا ۔ ہاں میں ابھی تجھ کو قیامت کی کچھ نشانیاں بتاتاہوں (جو یہ ہیں ) جبکہ باندی اپنے مولیٰ کو جنے گی اور اونٹوں کے چرواہے کالے کالے رنگ والے بڑی بڑی عمارتوں میں فخر و گھمنڈ کرنے لگیں گے۔ یہ (علم ِقیامت ) ان پانچ چیزوں میں سے ہے جن کوخدا کے سوا کوئی نہیں جانتا پھر حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے اِنَّ اللّٰہ عِنْدَہٗ عِلْمُ السَّاعَۃِ ( ترجمۂ کنز الایمان:بیشک اللّٰہ کے پاس ہے قیامت کا علم۔(پ۲۱،لقمٰن:۳۴)کی آیت تلاوت فرمائی (جس میں قیامت وغیرہ پانچ چیزوں کا ذکر ہے ) پھر وہ (سائل) واپس چلا گیا۔ اس کے بعد حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا کہ اس کو واپس بلالاؤ ۔ تو لوگوں کو کچھ نظر نہیں آیا تو حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا کہ یہ حضرت جبریل تھے جو لوگوں کو دین سکھانے کے لئے آئے تھے ۔", "roman": "Hazrat Abu Hurairah Radiyallahu Ta'ala Anhu se Riwayat hai unhon ne kaha ke ek din Huzoor Nabi Kareem Sallallahu Ta'ala Alaihi wa Aalihi wa Sallam logon se mulaqaat ke liye Makaan se baahar tashreef farma the to ek aadmi aaya aur us ne kaha ke Imaan kya hai? Huzoor Sallallahu Ta'ala Alaihi wa Aalihi wa Sallam ne farmaya ke Imaan yeh hai ke Allah ko aur us ke farishton ko aur us ki mulaqaat ko aur us ke Rasoolon ko aur maut ke baad uthne ko tu dil se maan le. Us ne kaha: Islam kya hai? To Huzoor Sallallahu Ta'ala Alaihi wa Aalihi wa Sallam ne farmaya ke Islam yeh hai ke tu khaas Allah Ta'ala hi ki ibaadat kare aur kisi ko us ka shareek na thehraye aur Namaz qaaim kare aur Zakat de jo Farz hai aur Ramazan ke roze rakhe. Us ne kaha ke Ihsaan kya hai? To Huzoor Sallallahu Ta'ala Alaihi wa Aalihi wa Sallam ne farmaya ke Ihsaan yeh hai ke tu Allah ki ibaadat is tarah kare goya ke tu Allah Ta'ala ko dekh raha hai, pas agar tu us ko nahi dekhta to (is tarah ibaadat kar ke) woh tujh ko dekh raha hai. Phir us ne kaha ke Qiyamat kab aayegi? To Huzoor Sallallahu Ta'ala Alaihi wa Aalihi wa Sallam ne farmaya ke jis se Sawaal kiya gaya hai woh Sawaal karne waale se zyada nahi jaanta. Haan main abhi tujh ko Qiyamat ki kuch nishaniyan batata hoon (jo yeh hain) jabke bandi apne Maula ko janegi aur oonton ke charwahe kaale kaale rang waale badi badi imaaraton mein fakhr o ghamand karne lagenge. Yeh (Ilm-e-Qiyamat) un paanch cheezon mein se hai jin ko Khuda ke siwa koi nahi jaanta, phir Huzoor Sallallahu Ta'ala Alaihi wa Aalihi wa Sallam ne \"Innal-Laha 'Indahoo 'Ilmus-Saa'ah\" (Tarjuma-e-Kanzul Imaan: Beshak Allah ke paas hai Qiyamat ka Ilm. [P21, Luqman: 34]) ki aayat tilawat farmai (jis mein Qiyamat waghairah paanch cheezon ka zikr hai) phir woh (saail) wapas chala gaya. Us ke baad Huzoor Sallallahu Ta'ala Alaihi wa Aalihi wa Sallam ne farmaya ke us ko wapas bula lao. To logon ko kuch nazar nahi aaya to Huzoor Sallallahu Ta'ala Alaihi wa Aalihi wa Sallam ne farmaya ke yeh Hazrat Jibreel the jo logon ko deen sikhaane ke liye aaye the."}, {"id": 6337, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 3, "arabic": "عَنْ اَبِیْ ھُرَیْرَۃَ عَنِ النَّبِیِّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ قَالَ:اَلْاِیْمَانُ بِضْعٌ وَّ سِتُّوْنَ شُعْبَۃً وَّالْحَیَائُ شُعْبَۃٌ مِّنَ الْاِیْمَانِ (صحیح البخاری،کتاب الایمان،باب امور الایمان، الحدیث:۹، ج۱،ص۱۵)", "urdu": "حضرت ابو ہریرہ رضی اللّٰہ تعالیٰ عنہ سے روایت ہے کہ حضور نبی صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے ارشاد فرمایا کہ ایمان کی شاخیں ساٹھ سے کچھ زیادہ ہیں اور’’ حیا‘‘ ایمان کی ایک بہت بڑی شاخ ہے۔ اس حدیث کو امام بخاری کے علاوہ مسلم ،نسائی ،ابودائود ،ابن ما جہ نے بھی اپنی اپنی کتابوں میں تحریر فرمایا ہے۔\nتوضیح ِالفاظ: بِضْعٌ کا لفظ گنتی میں تین سے لے کر نو تک کے عدد پر بولا جاتا ہے۔ شُعْبَۃٌ شاخ کو کہتے ہیں ۔ حَیَائٌ کا ترجمہ ’’شرم ‘‘ہے جس کو ہندی میں ’’لاج‘‘ بھی کہتے ہیں ۔ \nحضرت علامہ بیضاوی رَحْمَۃُ اللّٰہ تَعَالٰی عَلَیْہِ نے لفظ ِحیاء کی تفسیر فرماتے ہوئے تحریر فرمایا کہ اَلْحَیَائُ اِنْقِبَاضُ النَّفْسِ عَنِ الْقَبِیْحِ مُخَافَۃَ الذَّمِّ (بیضاوی شریف)یعنی مذمت کا خوف کرتے ہوئے برے کاموں سے نفس کا سکڑ جانا،اس کیفیت کا نام’’ حیا‘‘ہے۔ \n یہ در حقیقت ’’وَقاحَت ‘‘اور ’’خَجالت ‘‘کے درمیان کی ایک صفت ہے۔ ’’وقاحت‘‘ یہ ہے کہ انسان اس قدر بے شرم و بے غیرت بن جائے کہ اس کو کسی بُرے سے بُرے کام کرنے سے بھی کوئی جھجک ہی نہ ہو ۔اور ’’خجالت ‘‘یہ ہے کہ انسان اتنا شرمیلا ہوجائے کہ اچھے اور بُرے کام سے جھجکنے لگے اور ’’حیا‘‘یہ ہے کہ بُرے کاموں سے یہ خیال کرکے جھجک ہو کہ لوگ مذمت کریں گے اور اچھے کاموں سے کوئی جھجک نہ ہو۔ وقاحت اور خجالت یہ دونوں انسان کی مذموم اور بُری صفتیں ہیں اور حیاء انسان کی انتہائی محمود اور پسندیدہ صفت ہے۔", "roman": "Hazrat Abu Hurairah Radiyallahu Ta'ala Anhu se Riwayat hai ke Huzoor Nabi Sallallahu Ta'ala Alaihi wa Aalihi wa Sallam ne irshad farmaya ke Imaan ki shaakhein saath se kuch zyada hain aur \"Haya\" Imaan ki ek bahut badi shaakh hai. Is Hadees ko Imam Bukhari ke ilawa Muslim, Nasai, Abu Dawood, Ibn Majah ne bhi apni apni Kitaabon mein tehreer farmaya hai.\nTawzeeh-e-Alfaaz: Bidh'un ka lafz ginti mein teen se lekar nau tak ke adad par bola jaata hai. Shu'batun shaakh ko kehte hain. Haya'un ka tarjuma \"Sharm\" hai jis ko Hindi mein \"Laaj\" bhi kehte hain.\nHazrat Allama Baidawi Rahmatullah Ta'ala Alaih ne lafz-e-Haya ki tafseer farmate hue tehreer farmaya ke Al-Haya'u inqibaad-un-nafsi 'anil qabeehi makhaafataz-zamm (Baidawi Shareef) yaani mazammat ka khauf karte hue bure kaamon se nafs ka sukad jaana, is kaifiyyat ka naam \"Haya\" hai.\nYeh dar-haqeeqat \"Waqaahat\" aur \"Khajaalat\" ke darmiyan ki ek sifat hai. \"Waqaahat\" yeh hai ke insaan is qadar be-sharm o be-Ghairat ban jaaye ke us ko kisi bure se bure kaam karne se bhi koi jhijhak hi na ho. Aur \"Khajaalat\" yeh hai ke insaan itna sharmeela ho jaaye ke achhe aur bure kaam se jhijhakne lage aur \"Haya\" yeh hai ke bure kaamon se yeh khayal karke jhijhak ho ke log mazammat karenge aur achhe kaamon se koi jhijhak na ho. Waqaahat aur khajaalat yeh donon insaan ki mazmoom aur buri sifatein hain aur Haya insaan ki intehai mahmood aur pasandeeda sifat hai."}, {"id": 6338, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 4, "arabic": "عَنْ اَبِیْ مُوْسٰی الْاَشْعَرِیِّ قَالَ:قَالُوْا:یَارَسُوْلَ اللّٰہ اَیُّ الْاِسْلَامِ اَفْضَلُ قَالَ:مَنْ سَلِمَ الْمُسْلِمُوْنَ مِنْ لِّسَانِہٖ وَیَدِہٖ۔ ( صحیح البخاری،کتاب الایمان،باب ایّ الاسلام افضل؟،الحدیث:۱۱،ج۱،ص۱۶)", "urdu": ": حضرت ابو موسٰی اَشْعَری رضی اللّٰہ تعالیٰ عنہ سے روایت ہے،صحابہ نے عرض کی: یارسول اللّٰہ ! عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم کون سا اسلام افضل ہے؟ تو ارشاد فرمایا کہ اس شخص کا اسلام جس کی زبان اور ہاتھ سے تمام مسلمان سلامت رہیں ۔", "roman": "Hazrat Abu Moosa Ash'ari Radiyallahu Ta'ala Anhu se Riwayat hai, Sahabah ne arz ki: Ya Rasoolullah Azza wa Jall wa Sallallahu Ta'ala Alaihi wa Aalihi wa Sallam! Kaun sa Islam afzal hai? To irshad farmaya ke us Shakhs ka Islam jis ki zubaan aur haath se tamam Musalman salaamat rahein."}, {"id": 6339, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 5, "arabic": "عَنْ اَنَسٍ عَنِ النَّبِیِّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ قَالَ:لَا یُؤْمِنُ اَحَدُکُمْ حَتّٰی یُحِبَّ لِاَخِیْہِ مَا یُحِبُّ لِنَفْسِہٖ۔ ( صحیح البخاری،کتاب الایمان،باب من الایمان ان۔۔۔الخ، الحدیث:۱۳،ج۱،ص۱۶)", "urdu": "حضرت انَس رضی اللّٰہ تعالیٰ عنہ سے روایت ہے،حضور نبی صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا کہ تم میں سے کوئی مومن (کامل) نہیں ہوگاجب تک کہ اپنے بھائی (مومن) کے لئے وہی چیز نہ پسند کرے جو اپنی ذات کے لئے پسند کرتاہے۔", "roman": "Hazrat Anas Radiyallahu Ta'ala Anhu se Riwayat hai, Huzoor Nabi Sallallahu Ta'ala Alaihi wa Aalihi wa Sallam ne farmaya ke tum mein se koi Momin (kaamil) nahi hoga jab tak ke apne bhai (Momin) ke liye wahi cheez na pasand kare jo apni zaat ke liye pasand karta hai."}, {"id": 6340, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 6, "arabic": "عَنْ عَبْدِ اللّٰہ بْنِ عَمْرٍو اَنَّ النَّبِیَّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ قَالَ اَرْبَعٌ مَنْ کُنَّ فِیْہِ کَانَ مُنَافِقًا خالِصًا وَمَنْ کَانَتْ فِیْہِ خَصْلَۃٌ مِّنْھُنَّ کَانَتْ فِیْہِ خَصْلَۃٌ مِّنَ النِّفَاقِ حَتّٰی یَدَعَھَا اِذَا اؤْتُمِنَ خَانَ وَاِذَا حَدَّثَ کَذَبَ وَاِذَا عَاھَدَ غَدَرَ وَاِذَا خَاصَمَ فَجَرَ ( صحیح البخاری،کتاب الایمان،باب علامۃ المنافق، الحدیث:۳۴، ج۱، ص۲۵)", "urdu": "حضرت عبد اللّٰہ بن عمرو رضی اللّٰہ تعالیٰ عنہ سے روایت ہے کہ بے شک حضورنبی صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا:جس شخص میں یہ چار باتیں ہوں گی وہ خالص مُنافِق ہے اور جس شخص میں ان چار باتوں میں سے ایک بات ہوگی اس میں نِفاق کی ایک خصلت ہوگی یہاں تک کہ وہ اس کو چھوڑدے۔ { ۱ } جب امین بنایا جائے تو خیانت کرے { ۲ } جب بات کرے تو جھوٹ بولے { ۳ } اور جب کسی سے کوئی عہد کرے تو عہدشِکْنی کرے { ۴ } اور جب جھگڑا کرے تو بدزبانی کرے۔", "roman": "Hazrat Abdullah bin Amr Radiyallahu Ta'ala Anhu se Riwayat hai ke beshak Huzoor Nabi Sallallahu Ta'ala Alaihi wa Aalihi wa Sallam ne farmaya: Jis Shakhs mein yeh chaar baatein hongi woh khaalis munaafiq hai aur jis Shakhs mein in chaar baaton mein se ek baat hogi us mein nifaaq ki ek khaslat hogi yahan tak ke woh us ko chhor de. {1} Jab ameen banaya jaaye to khayanat kare {2} Jab baat kare to jhoot bole {3} Aur jab kisi se koi ahad kare to ahad-shikni kare {4} Aur jab jhagda kare to bad-zubaani kare."}, {"id": 6341, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 7, "arabic": "عَنْ عَامِرٍ قَالَ:سَمِعْتُ النُّعْمَانَ بْنَ بَشِیْرٍ یَقُوْلُ:سَمِعْتُ رَسُوْلَ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ یَقُوْلُ اَلْحَلَالُ بَیِّنٌ وَالْحَرَامُ بَیِّنٌ وَبَیْنَھُمَا مُشْتَبِھَاتٌ لَا یَعْلَمُھَا کَثِیْرٌ مِنَ النَّاسِ فَمَنِ اتَّقَی الْمُشَبَّھَاتِ اِسْتَبْرَأَ لِدِیْنِہٖ وَ عِرْضِہٖ وَمَنْ وَّقَعَ فیِ الشُّبُھَاتِ کَرَاعٍ یَرْعٰی حَوْلَ الْحِمٰی یُوْشِکُ اَنْ یُّوَاقِعَہٗ اَلَا وَاِنَّ لِکُلِّ مَلِکٍ حِمًی اَلَا اِنَّ حِمَی اللّٰہ فِیْ اَرْضِہٖ مَحَارِمُہٗ اَلَا وَاِنَّ فِی الْجَسَدِ مُضْغَۃً اِذَا صَلَحَتْ صَلَحَ الْجَسَدُ کُلُّہٗ وَاِذَا فَسَدَتْ فَسَدَ الْجَسَدُ کُلُّہٗ اَلَا وَھِیَ الْقَلْبُ (صحیح البخاری،کتاب الایمان،باب فضل من استبرأ لدینہ،الحدیث:۵۲،ج۱،ص۳۳)", "urdu": "عامر (شعبی) سے روایت ہے، انہوں نے کہا کہ میں نے حضرت نعمان بن بشیر رضی اللّٰہ تعالیٰ عنہ سے سنا، وہ کہتے تھے کہ میں نے رسول اللّٰہ عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم کو یہ فرماتے ہوئے سنا کہ حلال ظاہر ہے اور حرام ظاہر ہے اور ان دونوں کے درمیان کچھ مُشْتَبَہ چیزیں ہیں جن کو بہت سے لوگ نہیں جانتے تو جو کوئی شبہ کی چیزوں سے بچ گیا اس نے اپنے دین اور اپنی آبرو کو بچا لیا اور جو کوئی ان شبہ کی چیزوں میں پڑگیا تو اس کی مثال اس چرواہے کی ہے جو بادشاہ کی محفوظ چراگاہ کے آس پاس اپنے جانوروں کو چرائے تو ہوسکتا ہے کہ وہ جانور شاہی چراگاہ میں داخل ہوجائیں ۔سُن لو ! ہر بادشاہ کی ایک ’’حمی‘‘ (محفوظ و مخصوص چراگاہ) ہو تی ہے اور اللّٰہ عَزَّوَجَلَّ کی ’’حمی‘‘ اس کی زمین میں وہ چیزیں ہیں جن کو اس نے حرام ٹھہرایا ہے ۔خبردار! بدن میں ایک گوشت کی بوٹی ایسی ہے کہ اگر وہ درست ہے تو سارا بدن درست ہے اور اگر وہ فاسد ہوگئی تو سارا بدن بگڑ گیا سن لو! وہ دل ہے۔", "roman": "Aamir (Shabi) se Riwayat hai, unhon ne kaha ke main ne Hazrat Nu'man bin Basheer Radiyallahu Ta'ala Anhu se suna, woh kehte the ke main ne Rasoolullah Azza wa Jall wa Sallallahu Ta'ala Alaihi wa Aalihi wa Sallam ko yeh farmate hue suna ke Halal zaahir hai aur Haram zaahir hai aur in donon ke darmiyan kuch mushtabah cheezein hain jin ko bahut se log nahi jaante to jo koi shubhe ki cheezon se bach gaya us ne apne deen aur apni aabroo ko bacha liya aur jo koi in shubhe ki cheezon mein pad gaya to us ki misaal us charwahe ki hai jo baadshah ki mehfooz charaagah ke aas paas apne jaanwaron ko charaaye to ho sakta hai ke woh jaanwar shahi charaagah mein daakhil ho jayein. Sun lo! Har baadshah ki ek \"Hima\" (mehfooz o makhsoos charaagah) hoti hai aur Allah Azza wa Jall ki \"Hima\" us ki Zameen mein woh cheezein hain jin ko us ne Haram thehraya hai. Khabardaar! Badan mein ek gosht ki Booti aisi hai ke agar woh durust hai to saara badan durust hai aur agar woh Faasid ho gayi to saara badan bigad gaya, sun lo! Woh dil hai."}, {"id": 6342, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 8, "arabic": "قَالَ حُمَیْدُ بْنُ عَبْدِ الرَّحْمٰنِ:سَمِعْتُ مُعَاوِیَۃَ خَطِیْبًا یَقُوْلُ:سَمِعْتُ النَّبِیَّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ یَقُوْلُ:مَنْ یُّرِدِ اللّٰہ بِہٖ خَیْرًا یُّفَقِّھْہُ فِی الدِّیْنِ وَاِنَّمَا اَنَا قَاسِمٌ وَاللّٰہ یُعْطِیْ وَلَنْ تَزَالَ ھٰذِہِ الْاُمَّۃُ قَائِمَۃً عَلٰی اَمْرِاللّٰہ لَا یَضُرُّھُمْ مَنْ خَالَفَھُمْ حَتّٰی یَأتِیَ اَمْرُ اللّٰہ ( صحیح البخاری،کتاب العلم،باب من یرد اللّٰہ بہ۔۔۔الخ،الحدیث:۷۱،ج۱،ص۴۲)", "urdu": "حُمَیْد بن عبد الرحمن کہتے ہیں کہ میں نے حضرت امیر مُعاوِیہ رضی اللّٰہ تعالیٰ عنہ کو بحالت خطبہ یہ کہتے ہوئے سنا کہ حضور نبی اکرم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم فرماتے تھے کہ اللّٰہ تعالیٰ جس کے ساتھ بھلائی کا ارادہ فرماتا ہے اس کو دین کی سمجھ عطا فرماتا ہے اور میں تقسیم کرنے والا ہوں اور اللّٰہ تعالیٰ عطا فرماتا ہے اور اس امت کی ایک جماعت ہمیشہ اللّٰہ تعالیٰ کے دین پر قائم رہے گی،ان کے مخالفین ان کو کوئی نقصان نہیں پہنچاسکیں گے یہاں تک کہ اللّٰہ کا امر آجائے۔\nحضرت امیر مُعاوِیہ:اس حدیث کے راویوں میں حضرت امیر معاویہ رضی اللّٰہ تعالیٰ عنہ کی ہستی قابل ذکر ہے۔آپ سردارِ مکہ ابو سفیان رضی اللّٰہ تعالیٰ عنہ کے فرزند ہیں ۔آپ کی والدہ ماجدہ کا نام ’’ ہند ‘‘تھا ۔ ۸ھ ؁ فتح مکّہ کے سال آپ نے اسلام قبول کیا اور دربار رسالت میں اتنے مُعْتَمَد صحابی قرار پائے کہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے ’’کاتِبِ وَحی‘‘ کا عہدہ ان کو عطا فرمایا ۔خلافتِ راشدہ کے دور میں شام کے گورنر رہے ۔پھر تمام عالم اسلام کے بادشاہ ہوگئے۔رجب ۶۰ھ؁میں اٹھتّر برس کی عمرپاکر وفات پائی ۔آپ سے ایک سو چھتِّیس حدیثیں مروی ہیں ۔ (1) (فیوض الباری،ج۱،ص۲۲۶)", "roman": "Humaid bin Abdur Rahman kehte hain ke main ne Hazrat Ameer Muawiyah Radiyallahu Ta'ala Anhu ko bahalat-e-Khutbah yeh kehte hue suna ke Huzoor Nabi Akram Sallallahu Ta'ala Alaihi wa Aalihi wa Sallam farmate the ke Allah Ta'ala jis ke saath bhalai ka iradah farmata hai us ko deen ki samajh ata farmata hai aur main taqseem karne wala hoon aur Allah Ta'ala ata farmata hai aur is ummat ki ek Jama'at hamesha Allah Ta'ala ke deen par qaaim rahegi, un ke mukhalifeen un ko koi nuqsan nahi pohancha sakenge yahan tak ke Allah ka amr aa jaaye.\nHazrat Ameer Muawiyah: Is Hadees ke Raawiyon mein Hazrat Ameer Muawiyah Radiyallahu Ta'ala Anhu ki hasti qaabil-e-zikr hai. Aap Sardaar-e-Makkah Abu Sufyan Radiyallahu Ta'ala Anhu ke farzand hain. Aap ki walida majidah ka naam \"Hind\" tha. 8 Hijri Fath-e-Makkah ke saal aap ne Islam Qubool kiya aur darbaar-e-risalat mein itne mu'tamad Sahabi qaraar paaye ke Huzoor Sallallahu Ta'ala Alaihi wa Aalihi wa Sallam ne \"Kaatib-e-Wahi\" ka ohda un ko ata farmaya. Khilaafat-e-Raashidah ke daur mein Shaam ke governor rahe. Phir tamaam aalam-e-Islam ke baadshah ho gaye. Rajab 60 Hijri mein ath-hattar baras ki umr paakar wafaat paayi. Aap se ek sau chhatees Hadeesein Marwi hain. (1) (Fuyoodh-ul-Bari, Jild 1, Safha 226)"}, {"id": 6343, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 9, "arabic": "سَمِعْتُ رِبْعِیَّ بْنَ حِرَاشٍ یَقُوْلُ:سَمِعْتُ عَلِیًّا یَّقُوْلُ: قَالَ النَّبِیُّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ: لاَ تَکْذِبُوْا عَلَیَّ فَاِنَّہٗ مَنْ کَذَبَ عَلَیَّ فَلْیَلِجِ النَّارَ (صحیح البخاری،کتاب العلم،باب اثم من کذب علی النبی صلی اللّٰہ علیہ وسلم، الحدیث:۱۰۶،ج۱،ص۵۶)", "urdu": "رِبْعِی بن حراش کہتے ہیں کہ میں نے حضرت علی رضی اللّٰہ تعالیٰ عنہ کو یہ کہتے ہوئے سنا کہ نبی صلی ا ﷲ تعالیٰ علیہ و آلہ وسلم نے فرمایا: مجھ پر جھوٹ مت باندھو کیونکہ جو مجھ پر جھوٹ باندھے گا وہ ضرور جہنم میں داخل ہوگا۔", "roman": "Rib'ee bin Hirash kehte hain ke main ne Hazrat Ali RadiyAllahu Anhu ko yeh kehte hue suna ke Nabi Sallallahu Alayhi wa Sallam ne farmaya: Mujh par jhooth mat baandho kyonke jo mujh par jhooth baandhega woh zaroor Jahannam mein daakhil hoga."}, {"id": 6344, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 10, "arabic": "عَنِ ابْنِ عَبَّاسٍ قَالَ:مَرَّ النَّبِیُّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ بِقَبْرَیْنِ فَقَالَ: اِنَّھُمَا لَیُعَذَّبَانِ وَمَا یُعَذَّبَانِ فِیْ کَبِیْرٍ اَمَّا اَحَدُھُمَا فَکَانَ لاَ یَسْتَتِرُ مِنَ الْبَوْلِ وَاَمَّا الاٰخَرُ فَکَانَ یَمْشِیْ بِالنَّمِیْمَۃِ ثُمَّ اَخَذَ جَرِیْدَۃً رَطَبَۃً فَشَقَّھَا بِنِصْفَیْنِ ثُمَّ غَرَزَ فِیْ کُلِّ قَبْرٍ وَاحِدَۃً قَالُوْا: یَارَسُوْلَ اللّٰہ لِمَ صَنَعْتَ ھٰذَا؟فَقَالَ:لَعَلَّہٗ اَن یُّخَفَّفَ عَنْھُمَا مَا لَمْ یَیْبِسَا ( مشکاۃ المصابیح،کتاب الطھارۃ،باب آداب الخلائ، الحدیث:۳۳۸، ج۱، ص۸۱)", "urdu": "حضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُما سے روایت ہے انہوں نے کہا کہ حضور نبی صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم دو قبروں کے پاس سے گزرے تو ارشاد فرمایا کہ یقینایہ دونوں عذاب میں مبتلا ہیں اور کسی ایسے گناہ میں عذاب نہیں دیا جارہا ہے جس سے بچنا بہت زیادہ دشوار ہو ۔ان میں سے ایک تو پیشاب کے وقت پردہ نہیں کرتا تھا اور دوسرا چغل خوری کرتا تھا ۔پھر آپ نے کھجور کی ایک ہری ٹہنی لی اور اس کو چیر کر دو ٹکڑے کئے پھر ہر قبر میں ایک ایک ٹکڑا گاڑدیا ۔صحابہ نے عرض کیا کہ یارسول اللّٰہ ! عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم آپ نے ایسا کیوں کیا ؟ تو حضور صلی اللّٰہ تعالیٰ علیہ واٰلہ وسلم نے فرمایا : اس لئے کہ جب تک یہ ٹہنیاں خشک نہ ہوں گی ان دونوں کے عذاب میں تَخْفِیْف ہوجائے گی۔", "roman": "Hazrat Ibn Abbas RadiyAllahu Anhuma se Riwayat hai unhon ne kaha ke Huzoor Nabi Sallallahu Alayhi wa Sallam do Qabr'on ke paas se guzre to irshad farmaya ke yaqeenan yeh dono azaab mein mubtala hain aur kisi aise gunaah mein azaab nahin diya ja raha hai jis se bachna bahut zyada dushwaar ho. In mein se ek to Peshaab ke waqt Pardah nahin karta tha aur doosra chughalkhori karta tha. Phir Aap ne khajoor ki ek hari tehni li aur us ko cheer kar do tukde kiye phir har Qabr mein ek ek tukda gaad diya. Sahabah ne arz kiya ke Ya Rasoolullah! Azza wa Jall wa Sallallahu Alayhi wa Sallam Aap ne aisa kyon kiya? To Huzoor Sallallahu Alayhi wa Sallam ne farmaya: Is liye ke jab tak yeh tehniyan khushk na hongi in dono ke azaab mein takhfeef hojayegi."}, {"id": 6345, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 11, "arabic": "عَنْ اَنَسٍ عَنِ النَّبِیِّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ قَالَ:ثَلٰثٌ مَنْ کُنَّ فِیْہِ وَجَدَ حَلَاوَۃَ الاِْیْمَانِ اَنْ یَّکُوْنَ اللّٰہ وَرَسُوْلُہٗ اَحَبَّ اِلَیْہِ مِمَّا سِوَاھُمَا وَاَنْ یُّحِبَّ الْمَرْئَ لَا یُحِبُّہٗ اِلَّا لِلّٰہِ وَاَنْ یَّکْرَہَ اَنْ یَّعُوْدَ فِی الْکُفْرِکَمَا یَکْرَہُ اَنْ یُّقْذَفَ فِی النَّارِ ( صحیح البخاری،کتاب الایمان،باب حلاوۃ الایمان، الحدیث:۱۶، ج۱،ص۱۷)", "urdu": "حضرت اَنس رضی اللّٰہ تعالیٰ عنہ سے روایت ہے کہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا کہ تین چیزیں جس شخص میں ہوں وہ ایمان کی مٹھاس پائے گا { ۱ } جس کو اللّٰہ و رسول ان دونوں کے ماسوا (سارے جہان ) سے زیادہ مَحبوب ہوں ۔ { ۲ } اور جو کسی آدمی سے خاص اللّٰہ ہی کے لئے محبت رکھتا ہو { ۳ } اور جو اسلام قبول کرنے کے بعد پھر کفر میں جانے کو اتنا ہی بُرا جانے جتنا آگ میں جھونک دئیے جانے کو بُرا جانتا ہے۔", "roman": "Hazrat Anas RadiyAllahu Anhu se Riwayat hai ke Huzoor Sallallahu Alayhi wa Sallam ne farmaya ke teen cheezen jis Shakhs mein hon woh imaan ki mithaas payega { 1 } Jis ko Allah wa Rasool in dono ke masiwa (saare jahan) se zyada mehboob hon. { 2 } Aur jo kisi aadmi se khaas Allah hi ke liye Mohabbat rakhta ho { 3 } Aur jo Islam Qubool karne ke baad phir Kufr mein jaane ko itna hi bura jaane jitna aag mein jhonk diye jaane ko bura jaanta hai."}, {"id": 6346, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 12, "arabic": "عَنْ عُبَادَۃَ بْنِ الصَّامِتِ وَکَانَ شَہِدَ بَدْرًا وَّھُوَاَحَدُ النُّقَبَاءِ لَیْلَۃَ الْعَقَبَۃِ اَنَّ رَسُوْلَ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ قَالَ وَحَوْلَہٗ عِصَابَۃٌ مِنْ اَصْحَابِہٖ:بَایِعُوْنِیْ عَلٰی اَنْ لَّاتُشْرِکُوْا بِاللّٰہ شَیْئًا وَّلَاتَسْرِقُوْا وَلَاتَزْنُوْا وَلَاتَقْتُلُوْا اَوْلَادَکُمْ وَلَاتَأْتُوْا بِبُھْتَانٍ تَفْتَرُوْنَہٗ بَیْنَ اَیْدِیْکُمْ وَاَرْجُلِکُمْ وَلَا تَعْصُوْا فیِْ مَعْرُوْفٍ فَمَنْ وَّفیٰ مِنْکُمْ فَاَجْرُہٗ عَلَی اللّٰہ وَمَنْ اَصَابَ مِنْ ذٰلِکَ شَیْئًا فَعُوْقِبَ فیِ الدُّنْیَا فَھُوَ کَفَّارَۃٌ لَّہٗ وَ مَنْ اَصَابَ مِنْ ذٰلِکَ شَیْئًا ثُمَّ سَتَرَہٗ اللّٰہ فَھُوَ اِلَی اللّٰہ اِنْ شَائَ عَفَا عَنْہُ وَاِنْشَائَ عَاقَبَہٗ فَبَایَعْنَاہٗ عَلٰی ذٰلِکَ ( صحیح البخاری،کتاب الایمان، ۱۱۔باب، الحدیث:۱۸، ج۱، ص۱۷)", "urdu": "حضرت عبادہ بن صامت رضی اللّٰہ تعالیٰ عنہ (جو بدر کی لڑائی میں شریک ہوئے اور لیلۃُ الْعَقَبہ کے نقیبوں میں سے ایک ہیں ) سے روایت ہے کہ رسول اللّٰہ عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے اس حال میں جبکہ آپ کے گرد صحابہ کی ایک جماعت تھی،یہ فرمایا کہ تم لوگ مجھ سے بیعت کرو (ان باتوں پر) { ۱ }اللّٰہ تعالیٰ کے ساتھ کسی کو شریک نہ ٹھہرا ؤ گے { ۲ } چوری نہیں کروگے { ۳ } زنا نہیں کروگے { ۴ } اپنی اولاد کو قتل نہیں کروگے { ۵ } اپنے ہاتھ پائوں کے درمیان گھڑ کر کسی پر بہتان نہ باندھوگے { ۶ } کسی شرعی حکم میں نافرمانی نہیں کروگے۔ تو جو اس عَہْد و پَیمان کو پورا کرے گااس کا اجر اللّٰہ تعالیٰ کے ذمے ہے اور جو ان گناہوں میں سے کچھ کر بیٹھے اور اس کو دنیا میں اس کی سزا مل جائے تو یہ اس کے لئے کفارہ ہے اور جس نے ان گناہوں میں سے کسی گناہ کو کرلیا اور اللّٰہ تعالیٰ نے اس کے گناہ کو چھپائے رکھا تو اس کا معاملہ اللّٰہ کے حوالے ہے، وہ چاہے گا تو اس کو معاف فرمادے گا یا آخرت میں اس کو سزا دے گا، تو ہم سب لوگوں نے حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم سے اس بات پر بیعت کی۔", "roman": "Hazrat Ubada bin Samit RadiyAllahu Anhu (jo Badr ki ladayi mein shareek hue aur Lailat-ul-Aqabah ke naqeebon mein se ek hain) se Riwayat hai ke Rasoolullah Azza wa Jall wa Sallallahu Alayhi wa Sallam ne is haal mein jabke Aap ke gird Sahabah ki ek Jama'at thi, yeh farmaya ke tum log mujh se bai'at karo (in baaton par) { 1 } Allah Ta'ala ke saath kisi ko shareek na thehraoge { 2 } Chori nahin karoge { 3 } Zina nahin karoge { 4 } Apni Aulaad ko qatl nahin karoge { 5 } Apne haath paaon ke darmiyan ghad kar kisi par buhtan na baandhoge { 6 } Kisi shar'i Hukm mein nafarmani nahin karoge. To jo is ahd-o-paimaan ko poora karega us ka ajr Allah Ta'ala ke zimme hai aur jo in gunaahon mein se kuch kar baithe aur us ko duniya mein us ki saza mil jaye to yeh us ke liye Kaffarah hai aur jis ne in gunaahon mein se kisi gunaah ko kar liya aur Allah Ta'ala ne us ke gunaah ko chupaye rakha to us ka mamla Allah ke hawale hai, woh chahega to us ko maaf farma dega ya aakhirat mein us ko saza dega, to ham sab logon ne Huzoor Sallallahu Alayhi wa Sallam se is baat par bai'at ki."}, {"id": 6347, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 13, "arabic": "عَنْ اُمِّ سَلَمَۃَ قَالَتْ اِسْتَیْقَظَ النَّبِیُّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ ذَاتَ لَیْلَۃٍ فَقَالَ سُبْحَانَ اﷲِ مَاذَا اُنْزِلَ اللَّیْلَۃَ مِنَ الفِتَنِ وَمَاذَا فُتِحَ مِنَ الْخَزَائِنِ اَیْقِظُوْا صَوَاحِبَ الْحُجُرِ فَرُبَّ کَاسِیَۃٍ فِی الدُّنْیَا عَارِیَۃٌ فِی الْاٰخِرَۃِ ( صحیح البخاری،کتاب العلم،باب العلم والعظۃ باللیل، الحدیث:۱۱۵، ج۱،ص۶۱)", "urdu": "حضرت اُمّ ِسَلَمَہ رضی اللّٰہ تعالیٰ عنہا نے کہا کہ ایک رات حضور نبی صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم بیدار ہوئے تو فرمایا کہ سبحان اللّٰہ ! اس رات میں کیسے کیسے فتنے اتارے گئے اور کیسے کیسے خزانے کھولے گئے ان حجرے والیوں کو (عبادت کے لئے ) جگاؤ کیونکہ بہت سی عورتیں دنیا میں لباس پہنے ہوئے ہیں مگر وہ آخرت میں ننگی ہوں گی۔", "roman": "Hazrat Umm-e-Salamah Radiyallahu Anha ne kaha ke ek raat Huzoor Nabi Sallallahu Alayhi wa Sallam bedaar hue to farmaya ke SubhanAllah! Is raat mein kaise kaise fitne utare gaye aur kaise kaise khazane khole gaye in hujre waaliyon ko (ibadat ke liye) jagao kyonke bahut si auratein duniya mein Libaas pehne hue hain magar woh aakhirat mein nangi hongi."}, {"id": 6348, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 14, "arabic": "عَنْ جَرِیْرٍ اَنَّ النَّبِیَّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّم قَالَ لَہٗ فِیْ حَجَّۃِ الْوَدَاعِ: اِسْتَنْصِتِ النَّاسَ فَقَالَ:لَا تَرْجِعُوْا بَعْدِیْ کُفَّارًا یَضْرِبُ بَعْضُکُمْ رِقَابَ بَعْضٍ ( صحیح البخاری،کتاب العلم،باب الانصات للعلماء، الحدیث:۱۲۱، ج۱، ص۶۳)", "urdu": "حضرت جریر رضی اللّٰہ تعالیٰ عنہ سے روایت ہے کہ ان سے حضور نبی صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے ’’حجۃ الوداع‘‘ میں فرمایا کہ’’تم لوگوں کو خاموش کرو‘‘ پھر حضور نے فرمایا کہ تم لوگ میرے بعد پلٹ کر کُفَّار مت ہوجانا کہ تمہارا بعض بعض کی گردن مارے۔", "roman": "Hazrat Jareer RadiyAllahu Anhu se Riwayat hai ke un se Huzoor Nabi Sallallahu Alayhi wa Sallam ne \"Hajjat-ul-Wida\" mein farmaya ke \"Tum logon ko khamosh karo\" phir Huzoor ne farmaya ke tum log mere baad palat kar kuffaar mat hojana ke tumhara ba'az ba'az ki gardan mare."}, {"id": 6349, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 15, "arabic": "عَنْ اَبیْ ھُرَیْرَۃَ عَنِ النَّبِیِّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ اَنَّ رَجُلًا رَاٰی کَلْبًا یَأْکُلُ الثَّریٰ مِنَ العَطَشِ فَاَخَذَ الرَّجُلُ خُفَّہٗ فَجَعَلَ یَغْرِفُ لَہٗ بِہٖ حَتّٰی اَرْوَاہُ فَشَکَرَ اللّٰہ لَہٗ فَاَدْخَلَہُ الْجَنَّۃَ (صحیح البخاری،کتاب الوضوء،باب اذا شرب الکلب فی اناء احدکم۔۔۔ الخ، الحدیث:۱۷۳، ج۱،ص۸۳)", "urdu": "حضرت ابو ہریرہ رضی اللّٰہ تعالیٰ عنہ سے روایت ہے کہ حضور نبی صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا کہ ایک آدمی نے ایک کتے کو دیکھا جو پیاس کی و جہ سے گیلی مٹی چاٹ رہا تھا تو اس شخص نے اپنا موزہ لیا اور اس میں چلو سے پانی بھر کر اس کتے کو پلایا یہاں تک کہ وہ سیراب ہوگیا تو اللّٰہ تعالیٰ کو اس کا یہ کام پسند آیا اور اس کو جنت میں داخل کردیا۔", "roman": "Hazrat Abu Hurairah RadiyAllahu Anhu se Riwayat hai ke Huzoor Nabi Sallallahu Alayhi wa Sallam ne farmaya ke ek aadmi ne ek kutte ko dekha jo pyaas ki wajah se geeli mitti chaat raha tha to us Shakhs ne apna moza liya aur us mein Chullu se paani bhar kar us kutte ko pilaya yahan tak ke woh sairaab ho gaya to Allah Ta'ala ko us ka yeh kaam pasand aaya aur us ko jannat mein daakhil kar diya."}, {"id": 6350, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 16, "arabic": "عَنِ ابْنِ عُمَرَ عَنِ النَّبِیِّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ قَالَ:دَخَلَتْ اِمْْرَأَۃٌ النَّارَ فِیْ ھِرَّۃٍ رَبَطَتْہَا فَلَمْ تُطْعِمْھَا وَلَمْ تَدَعْھَا تَأْکُلُ مِنْ خُشَاشِ الْاَرْضِ ( صحیح البخاری،کتاب بدء الخلق،باب خمس من الدواب۔۔۔الخ، الحدیث:۳۳۱۸، ج۲،ص۴۰۸)", "urdu": ": حضرت عبد اللّٰہ بن عمر رضی اللّٰہ تعالیٰ عنہ روایت کرتے ہیں کہ حضور نبی صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا کہ ایک عورت ایک بلی کے معاملہ میں جہنم میں داخل ہوئی۔ اُس نے ایک بلی کو باندھ رکھا تھا نہ تو اس کو کچھ کھلایا نہ اس کو چھوڑا کہ وہ حشرات الارض کو کھاتی۔(یہاں تک کہ وہ بھوکی مرگئی)", "roman": "Hazrat Abdullah bin Umar RadiyAllahu Anhu Riwayat karte hain ke Huzoor Nabi Sallallahu Alayhi wa Sallam ne farmaya ke ek Aurat ek billi ke mamle mein Jahannam mein daakhil hui. Us ne ek billi ko baandh rakha tha na to us ko kuch khilaya na us ko choda ke woh hashrat-ul-arz ko khati. (Yahan tak ke woh bhooki mar gayi)"}, {"id": 6351, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 17, "arabic": "عَنْ اَبِیْ وَائِلٍ قَالَ:کَانَ عَبْدُ اللّٰہ یُذَکِّرُ النَّاسَ فِیْ کُلِّ خَمِیْسٍ فَقَالَ لَہٗ رَجُلٌ:یَا اَبَا عَبْدِ الرَّحْمٰنِ لَوَدِدْتُ اَنَّکَ ذَکَّرْتَنَا کُلَّ یَوْمٍ۔قَالَ:اَمَا اِنَّہٗ یَمْنَعُنِیْ مِنْ ذٰلِکَ اَنِّیْ اَکْرَہُ اَنْ اُمِلَّکُمْ وَاِنِّیْ اَتَخَوَّلُکُمْ بِالْمَوْعِظَۃِ کَمَا کَانَ النَّبِیُّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ یَتَخَوَّلُنَا بِھَا مَخَافَۃَ السَّامَۃِ عَلَیْنَا۔ (صحیح البخاری،کتاب العلم،باب من جعل لاھل العلم ایاما معلومۃ، الحدیث:۷۰، ۱،ص۴۲)", "urdu": "حضرت ابو وائل ( شقیق بن سلمہ ) سے روایت ہے کہ حضرت عبد اللّٰہ بن مسعود رضی اللّٰہ تعالیٰ عنہ ہر جمعرات کے دن وعظ فرمایا کرتے تھے تو ایک آدمی نے ان سے کہا کہ اے ابو عبد الرحمن!میری تمنا ہے کہ آپ روزانہ ہم کو وعظ سُنایا کریں تو آپ نے فرمایا کہ( روزانہ وعظ کہنے سے) جو چیز مجھے روکتی ہے وہ یہ ہے کہ میں تم لوگوں کو تنگی میں ڈالنا نہیں چاہتا اور تمہاری فرصت کا خیال رکھتا ہوں جیسے کہ نبی صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم وعظ سنانے میں ہماری فرصت کا خیال رکھتے تھے اس خوف سے کہ ہم اکتا نہ جائیں ۔", "roman": "Hazrat Abu Wael (Shaqeeq bin Salamah) se Riwayat hai ke Hazrat Abdullah bin Mas'ood RadiyAllahu Ta'ala Anhu har Jumeraat ke din wa'az farmaya karte the to ek aadmi ne un se kaha ke: Aye Abu Abdur Rahman! Meri tamanna hai ke aap rozana hum ko wa'az sunaya karein, to aap ne farmaya ke (rozana wa'az kehne se) jo cheez mujhe rokti hai woh yeh hai ke main tum logon ko tangi mein daalna nahi chahta aur tumhari fursat ka khayal rakhta hoon jaise ke Nabi Sallallahu Alayhi wa Sallam wa'az sunane mein hamari fursat ka khayal rakhte the is khauf se ke hum ukta na jayein."}, {"id": 6352, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 18, "arabic": "عَنْ اَبِیْ سَعِیْدٍ الخُدْرِیِّ اَنَّہٗ قَالَ: رَسُوْلُ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ یُوْشِکُ اَنْ یَّکُوْنَ خَیْرَ مَالِ الْمُسْلِمِ غَنَمٌ یَتْبَعُ بِھَا شَعَفَ الْجِبَالِ وَ مَوَاقِعَ القَطْرِ یَفِرُّ بِدِیْنِہٖ مِنَ الْفِتَنِ۔ ( صحیح البخاری،کتاب الایمان،باب من الدین الفرار من الفتن، الحدیث:۱۹،ج۱،ص۱۸)", "urdu": "حضرت اَبو سعید خُدْری رضی اللّٰہ تعالیٰ عنہ سے روایت ہے انہوں نے کہا کہ رسول اللّٰہ عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے ارشاد فرمایا ہے کہ عنقریب وہ زمانہ آئے گا کہ مسلمان کا بہترین مال بکریاں ہوں گی جن کے پیچھے پیچھے وہ پہاڑوں کی چوٹیوں اور بارش کے مقامات پر بھاگتا ہوا چلا جائے گاتاکہ وہ اپنے دین کو فتنوں سے بچالے۔", "roman": "Hazrat Abu Sa'eed Khudri RadiyAllahu Ta'ala Anhu se Riwayat hai unhon ne kaha ke Rasoolullah Azza wa Jall wa Sallallahu Alayhi wa Sallam ne irshad farmaya hai ke anqareeb woh zamana aayega ke Musalman ka behtareen Maal bakriyan hongi jin ke peeche peeche woh pahadon ki chotiyon aur baarish ke maqamaat par bhaagta hua chala jayega taake woh apne Deen ko fitnon se bacha le."}, {"id": 6353, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 19, "arabic": "عَنِ الْمَعْرُوْرِ قَالَ: لَقِیْتُ اَبَاذَرٍّ بِالرَّبَذَۃِ وَعَلَیْہِ حُلَّۃٌ وَعَلٰی غُلَامِہٖ حُلَّۃٌ فَسَئَلْتُہٗ عَنْ ذَالِکَ فَقَالَ: اِنِّیْ سَابَبْتُ رَجُلًا فَعَیَّرْتُہٗ بِاُمِّہٖ فَقَالَ لِیَ النَّبِیُّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ: یَا اَبَاذَرٍّ اَعَیَّرْتَہٗ بِاُمِّہٖ اِنَّکَ اِمْرَؤٌ فِیْکَ جَاہِلِیَّۃٌ اِخْوَانُکُمْ خَوَلُکُمْ جَعَلَھُمُ اللّٰہ تَحْتَ اَیْدِیْکُمْ فَمَنْ کَانَ اَخُوْہُ تَحْتَ یَدِہٖ فَلْیُطْعِمْہُ مِمَّا یَأْکُلُ وَ لْیُلْبِسْہُ مِمَّا یَلْبَسُ وَلَا تُکَلِّفُوْھُمْ مَا یَغْلِبُھُمْ فَاِنْ کَلَّفْتُمُوْھُمْ فَاَعِیْنُوْھُمْ۔( صحیح البخاری،کتاب الایمان،باب المعاصی من امر الجاھلیۃ۔۔۔الخ، الحدیث:۳۰، ج۱،ص۲۳)", "urdu": "حضرت مَعْرور سے روایت ہے، انہوں نے کہا کہ میں نے حضرت ابو ذر غِفَاری رضی اللّٰہ تعالیٰ عنہ سے ’’رَبَذَہ‘‘ میں ملاقات کی، وہ اور ان کا غلام ایک ہی جیسا جوڑا پہنے ہوئے تھے تو میں نے اس کے بارے میں ان سے سوال کیا تو حضرت ابوذر رضی اللّٰہ تعالیٰ عنہ نے فرمایا کہ میں نے ایک شخص سے گالی گلوچ کی اور اس کو ماں کی گالی دی تو حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا کہ اے ابوذر! تم نے اس کو ماں کی گالی دی تم ایسے آدمی ہو کہ تمہارے اندر جاہلیت کی خَصْلَت ہے تمہارے لونڈی غلام تمہارے (دینی) بھائی ہیں ۔ اللّٰہ تعالیٰ نے ان لوگوں کو تمہارا ماتحت بنادیا ہے تو جس کا بھائی اس کے ماتحت ہو اس کو چاہئے کہ جو خود کھائے اس کو کھلائے اور جو خود پہنے اس کو پہنائے اور تم ان خادموں کو ایسے کاموں کی تکلیف مت دو جو انہیں لاچار کردے اور اگر تم ایسی تکلیف دو تو خود بھی کام میں ان کی مددکرو۔", "roman": "Hazrat Ma'roor se Riwayat hai, unhon ne kaha ke main ne Hazrat Abu Zar Ghifari RadiyAllahu Ta'ala Anhu se \"Rabzah\" mein mulaqat ki, woh aur un ka ghulam ek hi jaisa joda pehne hue the to main ne is ke baare mein un se Sawaal kiya to Hazrat Abu Zar RadiyAllahu Ta'ala Anhu ne farmaya ke main ne ek Shakhs se gaali galoch ki aur us ko maa ki gaali di to Huzoor Sallallahu Alayhi wa Sallam ne farmaya ke: Aye Abu Zar! Tum ne us ko maa ki gaali di, tum aise aadmi ho ke tumhare andar jahiliyyat ki khaslat hai, tumhare laundi ghulam tumhare (deeni) bhai hain. Allah Ta'ala ne un logon ko tumhara maatahat bana diya hai, to jis ka bhai us ke maatahat ho us ko chahiye ke jo khud khaye us ko khilaye aur jo khud pehne us ko pehnaye, aur tum un khadimon ko aise kaamon ki takleef mat do jo unhein laachaar kar de, aur agar tum aisi takleef do to khud bhi kaam mein un ki madad karo."}, {"id": 6354, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 20, "arabic": "عَنْ اَبِیْ ھُرَیْرَۃَ قَالَ: قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ: اِذَا کَانَ اُمَرَائُکُمْ خِیَارَکُمْ وَاَغْنِیَائُکُمْ سَمْحَائَکُمْ وَاُمُوْرُکُمْ شُوْریٰ بَیْنَکُمْ فَظَھْرُ الْاَرْضِ خَیْرٌ لَّکُمْ مِنْ بَطْنِھَا وَاِذَا کَانَ اُمَرَائُکُمْ شِرَارَکُمْ وَاَغْنِیَائُکُمْ بُخَلَائَکُمْ وَ اُمُوْرُکُمْ اِلٰی نِسَائِکُمْ فَبَطْنُ الْاَرْضِ خَیْرٌ لَّکُمْ مِنْ ظَہْرِھا۔ رواہ الترمذی ( مشکاۃ المصابیح،کتاب الرقاق،باب تغیرالناس، الحدیث:۵۳۶۸، ج۲، ص۲۷۵)", "urdu": "حضرت ابو ہریرہ رضی اللّٰہ تعالیٰ عنہ سے روایت ہے، انہوں نے کہا کہ رسول اللّٰہ عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا کہ جب تمہارے اُمراء تم میں سے بہترین لوگ ہوں اور تمہارے مالدار سخی ہوں اور تمہارا معاملہ آپس کے مشوروں سے طے ہوتا رہے تو تمہارے لیے زمین کی پیٹھ زمین کے پیٹ سے بہتر ہے اور جب تمہارے اُمراء بدترین لوگ ہوں اور تمہارے مالدار بخیل ہوں اور تمہارے معاملات تمہاری عورتیں طے کرنے لگیں تو تمہارے لیے زمین کا پیٹ زمین کی پیٹھ سے بہتر ہے۔", "roman": "Hazrat Abu Hurairah RadiyAllahu Ta'ala Anhu se Riwayat hai, unhon ne kaha ke Rasoolullah Azza wa Jall wa Sallallahu Alayhi wa Sallam ne farmaya ke jab tumhare umara tum mein se behtareen log hon aur tumhare maaldaar sakhi hon aur tumhara ma'amlah aapas ke mashwaron se tay hota rahe to tumhare liye Zameen ki peeth Zameen ke pait se behtar hai, aur jab tumhare umara badtareen log hon aur tumhare maaldaar bakheel hon aur tumhare ma'amlaat tumhari auratein tay karne lagein to tumhare liye Zameen ka pait Zameen ki peeth se behtar hai."}, {"id": 6355, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 21, "arabic": "عَنِ ابْنِ عَبَّاسٍ قَالَ: مَا ظَھَرَ الْغُلُوْلُ فِیْ قَوْمٍ اِلَّا اَلْقَی اللّٰہ فِیْ قُلُوْبِھِمُ الرُّعْبَ وَلَا فَشَا الزِّنَا فِیْ قَوْمٍ اِلَّا کَثُرَ فِیْھِمُ الْمُوْتُ وَلَا نَقَصَ قَوْمٌ الْمِکْیَالَ وَالْمِیْزَانَ اِلَّا قُطِعَ عَنْھُمُ الرِّزْقُ وَلَا حَکَمَ قَوْمٌ بِغَیْرِ حَقٍّ اِلَّا فَشَا فِیْھِمُ الدَّمُ وَلَا خَتَرَ قَوْمٌ بِالْعَھْدِ اِلَّاسُلِّطَ عَلَیْھِِمُ العَدُوُّ (مشکاۃ المصابیح،کتاب الرقاق،باب تغیرالناس، الحدیث:۵۳۷۰، ج۲، ص۲۷۶)", "urdu": "حضرت عبد اللّٰہ بن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُما سے روایت ہے انہوں نے فرمایا کہ جب کسی قوم میں خیانت ظاہر اور کھلم کھلا ہونے لگتی ہے تو اللّٰہ تعالیٰ اس قوم کے دل میں اس کے دشمنوں کا خوف اور ڈر ڈال دیتا ہے اور جب کسی قوم میں زِنا کاری پھیل جاتی ہے تو اس قوم میں بکثرت موتیں ہونے لگتیں ہیں اور جو قوم ناپ تو ل میں کمی کرنے لگتی ہے اُس قوم کی روزی کاٹ دی جاتی ہے اور جوقوم ناحق فیصلہ کرنے لگتی ہے اس قوم میں خون ریزی پھیل جاتی ہے اور جو قوم عہد شکنی اور بد عہدی کرنے لگتی ہے اس قوم پر اس کے دشمن کو غالب و مسلط کردیا جاتا ہے۔", "roman": "Hazrat Abdullah bin Abbas RadiyAllahu Ta'ala Anhuma se Riwayat hai unhon ne farmaya ke jab kisi qaum mein khayanat zahir aur khullam khulla hone lagti hai to Allah Ta'ala us qaum ke dil mein us ke dushmano ka khauf aur darr daal deta hai aur jab kisi qaum mein zina-kaari phail jaati hai to us qaum mein bakasrat mautein hone lagti hain aur jo qaum naap tol mein kami karne lagti hai us qaum ki rozi kaat di jaati hai aur jo qaum na-haq faisla karne lagti hai us qaum mein khoon-rezi phail jaati hai aur jo qaum ahad-shikani aur bad-ahdi karne lagti hai us qaum par us ke dushman ko ghalib wa musallat kar diya jaata hai."}, {"id": 6356, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 22, "arabic": "عَنْ عَمْرِو بْنِ اَخْطَبَ الْاَ نْصَارِیِّ قَالَ: صَلَّی بِنَا رَسُوْلُ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ یَوْمًا الْفَجْرَ وَصَعِدَ عَلَی الْمِنْبَرِ فَخَطَبَنَا حَتّٰی حَضَرَتِ الظُّھْرُ فَنَزَلَ فَصَلَّی ثُمَّ صَعِدَ الْمِنْبَرَ فَخَطَبَنَا حَتّٰی حَضَرَتِ الْعَصْرُ ثُمَّ نَزَلَ فَصَلَّی ثُمَّ صَعِدَ الْمِنْبَرَ حَتّٰی غَرَبَتِ الشَّمْسُ فَاَخْبَرَنَا بِمَا ھُوَ کَائِنٌ اِلٰی یَوْمِ الْقِیٰمَۃِ قَالَ: فَاَعْلَمُنَا اَحْفَظُنَا ( مشکاۃ المصابیح،کتاب احوال القیامۃ وبدء الخلق،باب فی المعجزات، الحدیث:۵۹۳۶، ج۲،ص۳۹۷)", "urdu": "حضرت عَمْرو بن اَخْطَب اَنصاری رضی اللّٰہ تعالیٰ عنہ سے مروی ہے کہ انہوں نے کہا کہ ایک دن ہم لوگوں کو رسول اللّٰہ عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فجر کی نماز پڑھائی اور منبر پر چڑھ گئے اور ظہر کی نماز تک خطبہ پڑھتے رہے پھر اُترے اور نماز پڑھ کر پھرمنبر پر چڑھ گئے اور خطبہ دیتے رہے یہاں تک کہ عصر کی نماز کا وقت آگیا پھر اُترے اور نماز پڑھی پھرمنبر پر چڑھ گئے اور سورج ڈوبنے تک خطبہ پڑھتے رہے تو (اس دن بھر کے خطبہ میں ) ہم لوگوں کو حضور نے تمام ان چیزوں اور باتوں کی خبر دے دی جو قیامت تک ہونے والی ہیں تو ہم صحابہ میں سب سے بڑا عالم وہی ہے جس نے سب سے زیادہ اس خطبہ کو یاد رکھاہے۔", "roman": "Hazrat Amr bin Akhtab Ansari RadiyAllahu Ta'ala Anhu se Marwi hai ke unhon ne kaha ke ek din hum logon ko Rasoolullah Azza wa Jall wa Sallallahu Alayhi wa Sallam ne Fajr ki Namaz padhai aur Mimbar par chadh gaye aur Zuhr ki Namaz tak Khutbah padhte rahe, phir utre aur Namaz padh kar phir Mimbar par chadh gaye aur Khutbah dete rahe yahan tak ke Asr ki Namaz ka waqt aa gaya, phir utre aur Namaz padhi, phir Mimbar par chadh gaye aur sooraj doobne tak Khutbah padhte rahe, to (is din bhar ke Khutbah mein) hum logon ko Huzoor ne tamam un cheezon aur baaton ki khabar de di jo Qiyamat tak hone wali hain, to hum Sahabah mein sab se bada aalim wahi hai jis ne sab se zyada is Khutbah ko yaad rakha hai."}, {"id": 6357, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 23, "arabic": "عَنْ عَائِشَۃَ قَالَتْ: کَانَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ یَضَعُ لِحَسَّانَ مِنْبَرًا فِی الْمَسْجِدِ یَقُوْمُ عَلَیْہَا قَائِمًا یُّفَاخِرُ عَنْ رَسُوْلِ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ اَوْ یُنَافِحُ وَیَقُوْلُ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ: اِنَّ اللّٰہ یُؤَیِّدُ حَسَّانَ بِرُوْحِ الْقُدُسِ مَا نَافَحَ اَوْ فَاخَرَ عَنْ رَّسُوْلِ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ۔ رَوَاہُ الْبُخَارِی ( مشکاۃ المصابیح،کتاب الآداب،باب البیان والشعر، الحدیث: ۴۸۰۵،ج۲، ص۱۸۸)", "urdu": "حضرت بی بی عائشہ رضی اللّٰہ تعالیٰ عنہا سے روایت ہے، انہوں نے بیان کیا کہ رسول اللّٰہ عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم حضرت حسَّان کے لیے مسجد نبوی میں منبر رکھتے تھے اور حضرت حسَّان اس پر چڑھ کر کھڑے کھڑے رسول اللّٰہ عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم کی شان کے بارے میں فخریہ اَشعار پڑھتے یا حضور کی طرف سے مشرکین کی ہجو کا جواب دیتے تھے اور حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم فرماتے تھے کہ جب تک حسان میری طرف سے مدافعانہ جواب دیتے یامیرے بارے میں فخریہ اَشعار پڑھتے رہتے ہیں حضرت جبریل عَلَیْہِ السَّلَام ان کی مدد فرماتے رہتے ہیں ۔", "roman": "Hazrat Bibi Aisha RadiyAllahu Ta'ala Anha se Riwayat hai, unhon ne bayan kiya ke Rasoolullah Azza wa Jall wa Sallallahu Alayhi wa Sallam Hazrat Hassan ke liye Masjid-e-Nabwi mein Mimbar rakhte the aur Hazrat Hassan us par chadh kar khade khade Rasoolullah Azza wa Jall wa Sallallahu Alayhi wa Sallam ki shaan ke baare mein fakhriya ashaar padhte ya Huzoor ki taraf se mushrikeen ki hajo ka Jawab dete the aur Huzoor Sallallahu Alayhi wa Sallam farmate the ke jab tak Hassan meri taraf se mudafiyana Jawab dete ya mere baare mein fakhriya ashaar padhte rehte hain Hazrat Jibreel Alayhis Salam un ki madad farmate rehte hain."}, {"id": 6358, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 24, "arabic": "عَنِ ابْنِ مَسْعُوْدٍ اَنَّ رَسُوْلَ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ نَامَ عَلٰی حَصِیْرٍ فَقَامَ وَقَدْ اَثَّرَ فِیْ جَسَدِہٖ فَقَالَ ابْنُ مَسْعُوْدٍ: یَارَسُوْلَ اللّٰہ! لَوْ اَمَرْتَنَا اَنْ نَبْسُطَ لَکَ وَنَعْمَلَ فَقَالَ: مَا لِیْ وَلِلدُّنْیَا وَمَا اَنَا وَالدُّنْیَا اِلَّا کَرَاکِبٍ اِسْتَظَلَّ تَحْتَ شَجَرۃٍ ثُمَّ رَاحَ وَ تَرَکَہَا۔(مشکاۃ المصابیح،کتاب الرقاق،الفصل الثانی، الحدیث:۵۱۸۸، ج۲،ص ۲۴۷)", "urdu": "حضرت عبد اللّٰہ بن مسعود رضی اللّٰہ تعالیٰ عنہ سے روایت ہے کہ رسول اللّٰہ عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم ایک چٹائی پر سو کر جب اُٹھے تو آپ کے جسم مبارک پر چٹائی کا نشان پڑگیا تھا تو عبد اللّٰہ بن مسعود رضی اللّٰہ تعالیٰ عنہ نے عرض کیا کہ یارسول اللّٰہ ! عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم کاش! آپ ہم لوگوں کو حکم فرماتے کہ ہم لوگ آپ کے لیے بچھونا بچھا دیتے اور آپ کی راحت کا سامان کردیتے تو حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے ارشاد فرمایا کہ مجھے دنیا سے کیا مطلب میری اور دنیا کی مثال تو ایسی ہے جیسے کوئی سوار کسی درخت کے سایہ میں (کچھ دیر )بیٹھ جاتا ہے پھر اُس درخت کو چھوڑ کر چل دیتا ہے۔", "roman": "Hazrat Abdullah bin Mas'ood RadiyAllahu Ta'ala Anhu se Riwayat hai ke Rasoolullah Azza wa Jall wa Sallallahu Alayhi wa Sallam ek chatai par so kar jab uthe to aap ke jism-e-mubarak par chatai ka nishan pad gaya tha to Abdullah bin Mas'ood RadiyAllahu Ta'ala Anhu ne arz kiya ke: Ya Rasoolullah Azza wa Jall wa Sallallahu Alayhi wa Sallam! Kaash! Aap hum logon ko Hukm farmate ke hum log aap ke liye bichhona bichha dete aur aap ki rahat ka saaman kar dete to Huzoor Sallallahu Alayhi wa Sallam ne irshad farmaya ke mujhe dunya se kya matlab, meri aur dunya ki misaal to aisi hai jaise koi sawaar kisi darakht ke saaye mein (kuch der) baith jaata hai phir us darakht ko chhod kar chal deta hai."}, {"id": 6359, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 25, "arabic": "عَنْ عُبَادَۃَ بْنِ الصَّامِتِ اَنَّ النَّبِیَّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ قَالَ: اِضْمَنُوْا لِیْ سِتًّا مِّنْ اَنْفُسِکُمْ اَضْمَنْ لَکُمُ الْجَنَّۃَ اُصْدُقُوْا اِذَا حَدَّثْتُمْ وَاَوْفُوْا اِذَا وَعَدْتُمْ وَاَدُّوْا اِذَا ائْتُمِنْتُمْ وَاحْفَظُوْا فُرُوْجَکُمْ وَغُضُّوْا اَبْصَارَکُمْ وَکُفُّوْا اَیْدِیْکُمْ۔ (مشکاۃ المصابیح،کتاب الآداب،باب حفظ اللسان۔۔۔الخ، الحدیث:۴۸۷۰،ج۲،ص۱۹۷)", "urdu": "حضرت عُبادہ بن صامت رضی اللّٰہ تعالیٰ عنہ روایت کرتے ہیں کہ نبی صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا کہ تم لو گ اپنی طرف سے میرے لیے چھ چیزوں کی ذمہ داری قبول کرلو تو میں تمہارے لیے جنت کی ذمہ داری لیتا ہوں ۔ { ۱ } جب بات کرو تو سچ بولو { ۲ } جب کوئی وعدہ کرو اس کو پورا کرو { ۳ } جب کوئی امانت تم کو سونپی جائے تو اس امانت کو ادا کرو { ۴ } اپنی شرمگاہوں کی حفاظت کرو { ۵ } اپنی نگاہوں کو نیچی رکھو { ۶ } اپنے ہاتھوں کو (ہر ظلم و مَعْصِیَت سے ) روکے رکھو۔", "roman": "Hazrat Ubada bin Samit Radiyallahu Ta'ala Anhu Riwayat karte hain ke Nabi Sallallahu Alayhi wa Sallam ne farmaya ke tum log apni taraf se mere liye chhe cheezon ki zimmedari Qubool kar lo to main tumhare liye jannat ki zimmedari leta hoon. { 1 } Jab baat karo to sach bolo { 2 } Jab koi wada karo us ko poora karo { 3 } Jab koi amanat tum ko saunpi jaye to us amanat ko ada karo { 4 } Apni Sharmgahon ki hifazat karo { 5 } Apni nigahon ko neechi rakho { 6 } Apne haathon ko (har zulm-o-ma'siyat se) roke rakho."}, {"id": 6360, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 26, "arabic": "عَنْ اَبِیْ سَعِیْدٍ الْخُدْرِیِّ اَنَّ النَّبِیَّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ قَالَ: اِیَّاکُمْ وَالْجُلُوْسَ بِالطُّرُقَاتِ فَقَالُوْا: یَارَسُوْلَ اللّٰہ مَا لَنَا مِنْ مَّجَالِسِنَا بُدٌّ نَتَحَدَّثُ فِیْھَا فَقَالَ: فَاِذَا اَبَیْتُمْ اِلَّا الْمَجْلِسَ فَاَعْطُوْا الطَّرِیْقَ حَقَّہٗ قَالُوْا:وَمَا حَقُّ الطَّرِیْقِ یَا رَسُوْلَ اللّٰہ؟ قَالَ: غَضُّ الْبَصَرِ وَکَفُّ الْاَذیٰ وَرَدُّ السّلَامِ وَالْاَمْرُ بِالْمَعْرُوْفِ وَالنَّھْیُ عَنِ الْمُنْکَرِ (صحیح البخاری،کتاب الاستئذان،الحدیث:۶۲۲۹،ج۴،ص۱۶۵)", "urdu": "حضرت ابو سعید خدری رضی اللّٰہ تعالیٰ عنہ راوی ہیں کہ حضور نبی صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا کہ تم لوگ راستوں پر بیٹھنے سے بچو،تو صحابہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُم نے کہا کہ یارسول اللّٰہ ! عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم راستوں میں بیٹھنے سے تو ہم لوگوں کو چارہ ہی نہیں ہے کیونکہ ان ہی جگہوں میں تو ہم لوگ بیٹھ کر بات چیت کرتے ہیں ،تو حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا کہ اگر تم لوگ راستوں میں بیٹھنے سے باز نہیں رہ سکتے تو بیٹھو لیکن راستے کا حق دیتے رہو۔صحابہ رَضِیَ اللّٰہ تَعَالٰی عَنْہُم نے عرض کیا کہ یارسول اللّٰہ ! عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم راستہ کا کیا حق ہے؟ تو ارشاد فرمایا کہ { ۱ } نیچی نگاہ رکھنا { ۲ } کسی کو ایذا نہ دینا { ۳ } لوگوں کے سلام کا جواب دینا { ۴ } اچھی باتوں کا حکم دینا { ۵ } بُری باتوں سے منع کرنا۔", "roman": "Hazrat Abu Saeed Khudri Radiyallahu Ta'ala Anhu Raawi hain ke Huzoor Nabi Sallallahu Alayhi wa Sallam ne farmaya ke tum log raaston par baithne se bacho, to Sahabah Radiyallahu Ta'ala Anhum ne kaha ke Ya Rasoolullah! Azza wa Jall wa Sallallahu Alayhi wa Sallam raaston mein baithne se to hum logon ko charah hi nahi hai kyunke inhi jagahon mein to hum log baith kar baat cheet karte hain, to Huzoor Sallallahu Alayhi wa Sallam ne farmaya ke agar tum log raaston mein baithne se baaz nahi reh sakte to baitho lekin raaste ka haq dete raho. Sahabah Radiyallahu Ta'ala Anhum ne arz kiya ke Ya Rasoolullah! Azza wa Jall wa Sallallahu Alayhi wa Sallam raaste ka kya haq hai? To irshad farmaya ke { 1 } Neechi nigah rakhna { 2 } Kisi ko eeza na dena { 3 } Logon ke salam ka Jawab dena { 4 } Achhi baaton ka Hukm dena { 5 } Buri baaton se mana karna."}, {"id": 6361, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 27, "arabic": "عَنْ اَبِیْ ھُرَیْرَۃَ عَنِ النَّبِیِّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ قَالَ:مَا بَیْنَ بَیْتِیْ وَمِنْبَرِیْ رَوْضَۃٌ مِّنْ رِیَاضِالْجَنَّۃِ وَمِنْبَرِیْ عَلٰی حَوْضِیْ (صحیح البخاری،کتاب فضل الصلاۃ فی مسجد مکۃ و المدینۃ، باب فضل مابین القبر والمنبر،الحدیث:۱۱۹۶،ج۱،ص۴۰۳)", "urdu": "حضرت ابو ہریرہ رضی اللّٰہ تعالیٰ عنہ روایت کرتے ہیں کہ حضورنبی صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا کہ زمین کا جو حصّہ میرے گھر اور میرے منبر کے درمیان میں ہے وہ جنت کے باغوں میں سے ایک باغ ہے اور میرا منبر میرے حوض پر ہے۔", "roman": "Hazrat Abu Hurairah Radiyallahu Ta'ala Anhu Riwayat karte hain ke Huzoor Nabi Sallallahu Alayhi wa Sallam ne farmaya ke Zameen ka jo hissa mere ghar aur mere Mimbar ke darmiyan mein hai woh jannat ke baaghon mein se ek baagh hai aur mera Mimbar mere Hauz par hai."}, {"id": 6362, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 28, "arabic": "عَنْ اَنَسِ بْنِ مَالِکٍ اَنَّ عُمَرَ بْنَ الْخَطَّابِ رَضِیَ اللّٰہ عَنْہُ کَانَ اِذَا قُحِطُوْا اِسْتَسْقٰی بِالْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ رَضِیَ اللّٰہ عَنْہُ فَقَالَ:اَللّٰھُمَّ اِنَّا کُنَّا نَتَوَسَّلُ اِلَیْکَ بِنَبِیِّنَا فَتَسْقِیْنَا وَاِنَّا نَتَوَسَّلُ اِلَیْکَ بِعَمِّ نَبِیِّنَا فَاسْقِنَا قَالَ: فَیُسْقَوْنَ (صحیح البخاری،کتاب الاستسقاء،باب سؤال الناس الامام۔۔۔الخ،الحدیث:۱۰۱۰، ج۱،ص۳۴۶)", "urdu": "حضرت انس بن مالک رضی اللّٰہ تعالیٰ عنہ سے روایت ہے کہ حضرت عمر بن خطاب امیر المؤمنین رضی اللّٰہ تعالیٰ عنہ ،جب لوگ قحط سالی میں مبتلا ہوتے تھے تو حضرت عباس بن عبد المطلب کے وسیلہ سے بارش کی دُعا مانگا کرتے تھے اور یوں کہتے تھے کہ یا اللّٰہ ! عَزَّوَجَلَّ ہم تیری بارگاہ میں اپنے نبی کو وسیلہ بنایا کرتے تھے اس وقت تو ہم کو بارش سے سیراب فرماتا تھا اور اب ہم اپنے نبی کے چچا کوتیری بارگاہ میں وسیلہ بناتے ہیں لہٰذا تو ہم کو سیراب فرما دے تو لوگ سیراب کردئیے جاتے تھے۔(یعنی بارش ہوجاتی تھی)۔", "roman": "Hazrat Anas Bin Malik Radiyallahu Ta'ala Anhu se Riwayat hai ke Hazrat Umar bin Khattab Ameer-ul-Momineen Radiyallahu Ta'ala Anhu, jab log qaht-saali mein mubtala hote the to Hazrat Abbas bin Abdul Muttalib ke waseele se barish ki dua manga karte the aur yoon kehte the ke Ya Allah! Azza wa Jall hum Teri bargah mein apne Nabi ko waseela banaya karte the us waqt Tu hum ko barish se sairab farmata tha aur ab hum apne Nabi ke chacha ko Teri bargah mein waseela banate hain lihaza Tu hum ko sairab farma de to log sairab kar diye jaate the. (Ya'ni barish ho jaati thi)."}, {"id": 6363, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 29, "arabic": "عَنْ اَبِیْ بُرْدَۃَ قَالَ: قَدِمْتُ الْمَدِیْنَۃَ فَلَقِیَنِیْ عَبْدُ اللّٰہ بْنُ سَلَامٍ فَقَالَ لِیْ: اِنْطَلِقْ اِلَی الْمَنْزِلِ فَاَسْقِیْکَ فِیْ قَدَحٍ شَرِبَ فِیْہِ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ وَتُصَلِّیْ فِیْ مَسْجِدٍ صَلّٰی فِیْہِ النَّبِیُّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ فَانْطَلَقْتُ مَعَہٗ فَسَقَّانِیْ سَوِیْقًا وَاَطْعَمَنِیْ تَمْرًا وَصَلَّیْتُ فِیْ مَسْجِدِہٖ (صحیح البخاری،کتاب الاعتصام بالکتاب والسنۃ،باب ما ذکر النبی صلی اللّٰہ علیہ وسلم وحض علی اتفاق۔۔۔الخ، الحدیث:۷۳۴۱،ج۴،ص۵۱۸)", "urdu": "ابو بُردہ سے روایت ہے،انہوں نے کہا کہ میں مدینہ آیا تو مجھ سے حضرت عبد اللّٰہ بن سلام رضی اللّٰہ تعالیٰ عنہ نے ملاقات کی پھر فرمایا کہ تم گھرچلو میں تم کو اس پیالے میں کچھ پلاؤں گا جس پیالے میں رسول اللّٰہ عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے پیا تھا اور تم اُس مسجد میں نماز پڑھوگے جس میں نبی صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے نماز پڑھی تھی۔ چنانچہ میں ان کے ساتھ گیا تو انہوں نے مجھ کو (اُس پیالہ میں ) ستوپلایااور کھجورکھلائی اور میں نے ان کی مسجد میں نماز پڑھی۔", "roman": "Abu Burdah se Riwayat hai, unhon ne kaha ke main Madinah aaya to mujh se Hazrat Abdullah bin Salam Radiyallahu Ta'ala Anhu ne mulaqat ki phir farmaya ke tum ghar Chullu main tum ko us pyale mein kuch pilaonga jis pyale mein Rasoolullah Azza wa Jall wa Sallallahu Alayhi wa Sallam ne piya tha aur tum us Masjid mein Namaz padhoge jis mein Nabi Sallallahu Alayhi wa Sallam ne Namaz padhi thi. Chunanche main un ke saath gaya to unhon ne mujh ko (us pyale mein) sattoo pilaya aur khajoor khilayi aur main ne un ki Masjid mein Namaz padhi."}, {"id": 6364, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 30, "arabic": "عَنْ سَعِیْدِ بْنِ اَبِی الْحَسَنِ قَالَ: کُنْتُ عِنْدَ ابْنِ عَبَّاسٍ اِذْ جَائَ ہٗ رَجُلٌ فَقَالَ: یَا اِبْنَ عَبَّاسٍ اِنِّیْ رَجُلٌ اِنَّمَا مَعِیْشَتِیْ مِنْ صَنْعَۃِ یَدِیْ وَاِنِّیْ اَصْنَعُ ھٰذِہِ التَّصَاوِیْرَ فَقَالَ: ابْنُ عَبَّاسٍ لَا اُحَدِّثُکَ اِلَّا مَا سَمِعْتُ مِنْ رَسُوْلِ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ سَمِعْتُہٗ یَقُوْلُ: مَنْ صَوَّرَ صُوْرَۃً فَاِنَّ اللّٰہ مُعَذِّبُہٗ حَتّٰی یَنْفُخَ فِیْہِ الرُّوْحَ وَلَیْسَ بِنَافِخٍ فِیْھَا اَبَدًا فَرَبَا الرَّجُلُ رَبْوَۃً شَدِیْدَۃً وَاصْفَرَّ وَجَھُہٗ فَقَالَ: وَیْحَکَ اِنْ اَبَیْتَ اِلَّا اَنْ تَصْنَعَ فَعَلَیْکَ بِھٰذا الشَّجَرِ وَکُلِّ شَیْیٍٔ لَیْسَ فَیْہِ رُوْحٌ (مشکاۃ المصابیح،کتاب اللباس،باب التصاویر، الحدیث:۴۵۰۷، ج۲،ص ۱۴۰)", "urdu": "سعید بن ابی الحسن راوی ہیں انہوں نے کہا کہ میں حضرت ابن عباس رَضِیَ اللّٰہ تَعَالٰی عَنْہُما کے پاس تھا کہ ناگہاں ان کے پاس ایک آدمی آیا اور کہا کہ اے ابن عباس! میں ایسا آدمی ہوں کہ میری روزی میرے ہاتھ کی کاریگری سے چلتی ہے اور میں ان تصویروں کو بناتا ہوں ، تو ابن عباس نے فرمایا کہ تم سے وہی حدیث بیان کرتا ہوں جس کو میں نے خود رسول اللّٰہ عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم سے سُنا ہے ۔میں نے حضور کو یہ فرماتے ہوئے سُنا ہے کہ جو شخص تصویر بنائے گا اللّٰہ تعالیٰ اس کو اس وقت تک عذاب دے گا جب تک کہ وہ اس تصویر میں روح نہ پھونک دے اور وہ اس تصویر میں کبھی بھی روح نہیں پھونک سکے گا تو اس آدمی نے لمبا سانس کھینچا اور (خوف سے )پیلا پڑگیا۔ پھر ابن عباس نے فرمایا کہ تیرا ناس ہو اگر تو اس کے بنانے سے بازنہیں رہ سکتا تو ان درختوں اور بے جان والی چیزوں کی تصویر بنایا کر۔", "roman": "Saeed bin Abil Hasan Raawi hain unhon ne kaha ke main Hazrat Ibn Abbas Radiyallahu Ta'ala Anhuma ke paas tha ke nagahan un ke paas ek aadmi aaya aur kaha ke Aye Ibn Abbas! Main aisa aadmi hoon ke meri rozi mere haath ki karigari se chalti hai aur main in Tasweeron ko banata hoon, to Ibn Abbas ne farmaya ke tum se wahi Hadees bayan karta hoon jis ko main ne khud Rasoolullah Azza wa Jall wa Sallallahu Alayhi wa Sallam se suna hai. Main ne Huzoor ko yeh farmate hue suna hai ke jo Shakhs Tasweer banaye ga Allah Ta'ala us ko us waqt tak azaab dega jab tak ke woh us Tasweer mein rooh na phoonk de aur woh us Tasweer mein kabhi bhi rooh nahi phoonk sakega to us aadmi ne lamba saans khencha aur (khauf se) peela pad gaya. Phir Ibn Abbas ne farmaya ke tera naas ho agar tu is ke banane se baaz nahi reh sakta to in darakhton aur be-jaan wali cheezon ki Tasweer banaya kar."}, {"id": 6365, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 31, "arabic": "عَنْ سَعِیْدِ بْنِ اَبِی الْحَسَنِ قَالَ: کُنْتُ عِنْدَ ابْنِ عَبَّاسٍ اِذْ جَائَ ہٗ رَجُلٌ فَقَالَ: یَا اِبْنَ عَبَّاسٍ اِنِّیْ رَجُلٌ اِنَّمَا مَعِیْشَتِیْ مِنْ صَنْعَۃِ یَدِیْ وَاِنِّیْ اَصْنَعُ ھٰذِہِ التَّصَاوِیْرَ فَقَالَ: ابْنُ عَبَّاسٍ لَا اُحَدِّثُکَ اِلَّا مَا سَمِعْتُ مِنْ رَسُوْلِ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ سَمِعْتُہٗ یَقُوْلُ: مَنْ صَوَّرَ صُوْرَۃً فَاِنَّ اللّٰہ مُعَذِّبُہٗ حَتّٰی یَنْفُخَ فِیْہِ الرُّوْحَ وَلَیْسَ بِنَافِخٍ فِیْھَا اَبَدًا فَرَبَا الرَّجُلُ رَبْوَۃً شَدِیْدَۃً وَاصْفَرَّ وَجَھُہٗ فَقَالَ: وَیْحَکَ اِنْ اَبَیْتَ اِلَّا اَنْ تَصْنَعَ فَعَلَیْکَ بِھٰذا الشَّجَرِ وَکُلِّ شَیْیٍٔ لَیْسَ فَیْہِ رُوْحٌ ( مشکاۃ المصابیح،کتاب اللباس،باب التصاویر، الحدیث:۴۵۰۷، ج۲،ص ۱۴۰)", "urdu": "حضرت عُقبہ رضی اللّٰہ تعالیٰ عنہ سے روایت ہے کہ حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم ایک دن گھر سے باہر تشریف لے گئے اور’’شہداء ِاُحُد‘‘کی قبروں پر اس طرح نماز پڑھی جیسے میت پر نماز پڑھی جاتی ہے پھر پلٹ کر منبر پر رونق اَفروز ہوئے اور ارشاد فرمایا کہ میں تمہارا پیش رو اور تمہارا گواہ ہوں اور میں خدا کی قسم! اپنے حوض کو اس وقت دیکھ رہا ہوں اور بے شک مجھ کو زمین کے خزانوں کی کنجیاں دے دی گئی ہیں اور میں بخدا یقین کے ساتھ کہتا ہوں کہ مجھ کو تم لوگوں کے بارے میں ذرا بھی یہ ڈر نہیں ہے کہ تم لوگ میرے بعد مشرک ہوجاؤ گے لیکن مجھے یہ خوف ہے کہ تم لوگ دنیا میں رغبت اور ایک دوسرے پر حسد کروگے۔", "roman": "Hazrat Uqbah Radiyallahu Ta'ala Anhu se Riwayat hai ke Huzoor Sallallahu Alayhi wa Sallam ek din ghar se bahar tashreef le gaye aur 'Shuhada-e-Uhud' ki Qabron par is tarah Namaz padhi jaise Mayyit par Namaz padhi jaati hai phir palat kar Mimbar par raunaq-afroz hue aur irshad farmaya ke main tumhara pesh-rau aur tumhara Gawah hoon aur main Khuda ki qasam! Apne Hauz ko is waqt dekh raha hoon aur beshak mujh ko Zameen ke khazanon ki kunjiyan de di gayi hain aur main bakhuda yaqeen ke saath kehta hoon ke mujh ko tum logon ke baare mein zara bhi yeh dar nahi hai ke tum log mere baad mushrik ho jaoge lekin mujhe yeh khauf hai ke tum log duniya mein raghbat aur ek doosre par hasad karoge."}, {"id": 6366, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 32, "arabic": "عَنْ زَارِعٍ وَکَانَ فِیْ وَفْدِ عَبْدِ الْقَیْسِ قَالَ: لَمَّا قَدِمْنَا الْمَدِیْنَۃَ فَجَعَلْنَا نَتَبَادَرُ مِنْ رَّوَاحِلِنَا فَنُقَبِّلُ یَدَ رَسُوْلِ اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَسَلَّمَ وَرِجْلَہٗ۔ ( مشکاۃ المصابیح،کتاب الآداب، باب المصافحۃ والمعانقۃ، الحدیث: ۴۶۸۸، ج۲،ص۱۷۱)", "urdu": "حضرت زارِع جو قبیلہ عبد الْقَیْس کے نمائندوں میں شامل تھے فرماتے ہیں کہ جب ہم مدینہ میں آئے توہم لوگ جلدی جلدی اپنی سواریوں سے اتر پڑے اور ہم حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم کے ہاتھ اور پاؤں کو بوسہ دینے لگے۔", "roman": "Hazrat Zari' jo qabeela Abdul Qais ke numaindon mein shamil the farmate hain ke jab hum Madinah mein aaye to hum log jaldi jaldi apni sawariyon se utar pade aur hum Huzoor Sallallahu Alayhi wa Sallam ke haath aur paaon ko bosa dene lage."}, {"id": 6367, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 33, "arabic": "عَنْ اَبِیْ ھُرَیْرَۃَ اَنَّ رَسُوْلَ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ قَالَ: ثَلٰثٌ مُنْجِیَاتٌ وَثَلٰثٌ مُھْلِکَاتٌ فَاَمَّا الْمُنْجِیَاتُ فَتَقْوَی اللّٰہ فِی السِّرِّ وَالْعَلَانِیَۃِ وَالْقَوْلُ بِالْحَقِّ فِی الرِّضٰی وَالسَّخَطِ وَالْقَصْدُ فِی الْغِنٰی وَالْفَقْرِ وَاَمَّا الْمُہْلِکَاتُ فَھَوًی مُتَّبَعٌ وَشُحٌ مُطَاعٌ وَاِعْجَابُ الْمَرْئِ بِنَفْسِہٖ وَھِیَ اَشَدُّھُنَّ ( مشکاۃ المصابیح،کتاب الآداب،باب الغضب والکبر، الحدیث: ۵۱۲۲، ج۲،ص۲۳۵)", "urdu": "حضرت ابو ہریرہ رضی اللّٰہ تعالیٰ عنہ راوی ہیں کہ رسو ل اللّٰہ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا کہ تین(خصلتیں )نجات دلانے والی اور تین(خصلتیں )ہلاکت میں ڈالنے والی ہیں ۔نجات دلانے والی (خصلتیں )یہ ہیں : { ۱ } ظاہر و باطن میں اللّٰہ سے ڈرنا { ۲ } خوشی و ناراضگی میں حق بولنا { ۳ } مالداری اور فقیری میں درمیانی چال چلنا، اور ہلاکت میں ڈالنے والی (خصلتیں )یہ ہیں : { ۱ } نفسانی خواہشوں کی پیروی کرنا { ۲ } بخیلی کی اطاعت کرنا { ۳ } اپنی ذات پر َگھمنڈ کرنا اور یہ ان تینوں میں سب سے زیادہ سخت ہے۔", "roman": "Hazrat Abu Hurairah RadiyAllahu Anhu Raawi hain ke Rasoolullah Sallallahu Alayhi wa Sallam ne farmaya ke teen (khaslatein) nijaat dilane wali aur teen (khaslatein) halakat mein daalne wali hain. Nijaat dilane wali (khaslatein) yeh hain: { 1 } Zahir o baatin mein Allah se darna { 2 } Khushi o narazgi mein haq bolna { 3 } Maaldari aur faqeeri mein darmiyani chaal chalna, aur halakat mein daalne wali (khaslatein) yeh hain: { 1 } Nafsani khwahishon ki pairwi karna { 2 } Bakheeli ki Ita'at karna { 3 } Apni zaat par ghamand karna aur yeh un teeno mein sab se zyada sakht hai."}, {"id": 6368, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 34, "arabic": "عَنْ اَبِیْ سَعِیْدٍ وَجَابِرٍ قَالَا: قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ: اَلْغِیْبَۃُ اَشَدُّ مِنَ الزِّنَا قَالُوْا: یَارَسُوْلَ اللّٰہ وَکَیْفَ الْغِیْبَۃُ اَشَدُّ مِنَ الزِّنَا؟ قَالَ: اِنَّ الرَّجُلَ لَیَزْنِیْ فَیَتُوْبُ فَیَتُوْبُ اللّٰہ عَلَیْہِ وَفِیْ رِوَایَۃٍ فَیَتُوْبُ فَیَغْفِرُ اللّٰہ لَہٗ وَاِنَّ صَاحِبَ الْغِیْبَۃِ لَا یُغْفَرُ لَہٗ حَتّٰی یَغْفِرَھَا لَہٗ صَاحِبُہٗ ( مشکاۃ المصابیح،کتاب الآداب،باب حفظ اللسان۔۔۔الخ، الحدیث:۴۸۷۴۔۴۸۷۵، ج۲،ص۱۹۸)", "urdu": "حضرت ابو سعید و حضرت جابر رَضِیَ اللّٰہ تَعَالٰی عَنْہُما سے مروی ہے کہ رسول اللّٰہ عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا کہ غیبت زنا سے زیادہ سخت (گناہ) ہے تو صحابہ نے کہا کہ یارسول اللّٰہ ! عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم غیبت زنا سے زیادہ سخت (گناہ) کس طرح ہے؟ تو حضور نے فرمایا کہ آدمی زنا کرتا ہے پھر توبہ کرلیتا ہے تو اللّٰہ تعالیٰ اس کی توبہ قبول فرما کر اس کو بخش دیتا ہے لیکن غیبت کرنے والے کو خداوند تعالیٰ اس وقت تک نہیں بخشے گا جب تک اس کو وہ شخص معاف نہ کردے جس کی اس نے غیبت کی ہے۔", "roman": "Hazrat Abu Saeed wa Hazrat Jabir Radiyallahu Anhuma se Marwi hai ke Rasoolullah Azza wa Jall wa Sallallahu Alayhi wa Sallam ne farmaya ke gheebat zina se zyada sakht (gunah) hai to Sahabah ne kaha ke Ya Rasoolullah! Azza wa Jall wa Sallallahu Alayhi wa Sallam gheebat zina se zyada sakht (gunah) kis tarah hai? To Huzoor ne farmaya ke aadmi zina karta hai phir Taubah kar leta hai to Allah Ta'ala us ki Taubah Qubool farma kar us ko bakhsh deta hai lekin gheebat karne wale ko Khudawand Ta'ala us waqt tak nahi bakhshe ga jab tak us ko woh Shakhs maaf na kar de jis ki us ne gheebat ki hai."}, {"id": 6369, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 35, "arabic": "عَنْ اَبِیْ ھُرَیْرَۃَ اَنَّ رَسُوْلَ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ قَالَ: لَیْسَ الشَّدِیْدُ بِالصُّرَعَۃِ اِنَّمَا الشَّدِیْدُ الَّذِیْ یَمْلِکَ نَفَسَہٗ عِنْدَ الْغَضَبِ (صحیح مسلم،کتاب البر۔۔۔الخ،باب فضل من یملک نفسہ۔۔۔الخ،الحدیث:۲۶۰۸،ص۱۴۰۶)", "urdu": "حضرت ابو ہریر ہ رضی اللّٰہ تعالیٰ عنہ راوی ہیں کہ رسول اللّٰہ عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرما یا کہ لوگوں کو پچھاڑ دینے والا پہلوان نہیں ہے پہلوان تو وہی ہے جو غصہ کے وقت اپنے نفس کا مالک ہے۔", "roman": "Hazrat Abu Hurairah RadiyAllahu Anhu Raawi hain ke Rasoolullah Azza wa Jall wa Sallallahu Alayhi wa Sallam ne farmaya ke logon ko pachhaad dene wala pehlwan nahi hai pehlwan to wahi hai jo gusse ke waqt apne nafs ka maalik hai."}, {"id": 6370, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 36, "arabic": "عَنْ اَنَسٍ قَالَ: قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ: مَنْ اَحَبَّ اَنْ یُّبْسَطَ لَہٗ فِیْ رِزْقِہٖ وَیُنْسَاَ لَہٗ فِیْ اَثَرِہٖ فَلْیَصِلْ رَحِمَہٗ ( مشکاۃ المصابیح،کتاب الآداب،باب البر والصلۃ، الحدیث: ۴۹۱۸،ج۲، ص۲۰۵)", "urdu": "حضرت انس بن مالک رضی اللّٰہ تعالیٰ عنہ سے روایت ہے، انہوں نے کہا کہ میں نے رسول اللّٰہ عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم کو یہ فرماتے ہوئے سُنا ہے کہ جس شخص کو یہ اچھا لگے کہ اس کی روزی میں فراخی اور اس کی عمر میں درازی ہو تو اس کو چاہئے کہ اپنے رشتہ داروں کے ساتھ نیک سلوک کرے۔", "roman": "Hazrat Anas Bin Malik RadiyAllahu Anhu se Riwayat hai, unhon ne kaha ke main ne Rasoolullah Azza wa Jall wa Sallallahu Alayhi wa Sallam ko yeh farmate hue suna hai ke jis Shakhs ko yeh achha lage ke us ki rozi mein farakhi aur us ki umr mein darazi ho to us ko chahiye ke apne rishtedaron ke saath naik sulook kare."}, {"id": 6371, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 37, "arabic": "عَنْ اَبِیْ ھُرَیْرَۃَ قَالَ: قَالَ رَسُوْلُ اللّٰہ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ: اِذَا مَاتَ الْاِنْسَانُ اِنْقَطَعَ عَنْہُ عَمَلُہٗ اِلَّا مِنْ ثَلٰثَۃٍ اِلَّا مِنْ صَدَقَۃٍ جَارِیَۃٍ اَوْعِلْمٍ یُّنْتَفَعُ بِہٖ اَوْ وَلَدٍ صَالِحٍ یَدْعُوْ لَہٗ۔ رَوَاہ مُسْلِم۔ ( مشکاۃ المصابیح،کتاب العلم،الفصل الاوّل، الحدیث:۲۰۳، ج۱،ص۶۰)", "urdu": "حضرت ابو ہریر ہ رضی اللّٰہ تعالیٰ عنہ نے کہا کہ رسول اللّٰہ عَزَّوَجَلَّ و صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا ہے کہ جب انسا ن مرجاتا ہے تو اس سے اس کے عمل کا ثواب کٹ جاتا ہے مگر تین عمل سے (کہ ان کا ثواب مرنے کے بعد بھی ملتا رہتا ہے ) { ۱ } صدقہ جاریہ کا ثواب { ۲ } یا اس علم کاثواب جس سے لوگ فائدہ اٹھائیں { ۳ } یانیک اولاد جو اس کے لیے دعا کرتی رہے۔", "roman": "Hazrat Abu Hurairah RadiyAllahu Anhu ne kaha ke Rasoolullah Azza wa Jall wa Sallallahu Alayhi wa Sallam ne farmaya hai ke jab insaan mar jata hai to us se us ke amal ka sawab kat jata hai magar teen amal se (ke un ka sawab marne ke baad bhi milta rehta hai) { 1 } Sadaqah-e-Jariyah ka sawab { 2 } ya us Ilm ka sawab jis se log faida uthayein { 3 } ya naik Aulaad jo us ke liye Dua karti rahe."}, {"id": 6372, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 38, "arabic": "اَنَّ عَائِشَۃَ زَوْجَ النَّبِیِّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ قَالَتْ: جَائَ تْنِیْ اِمْرَأَۃٌ وَمَعَھَا اِبْنَتَانِ لَھَا فَسَئَلَتْنِیْ فَلَمْ تَجِدْ عِنْدِیْ شَیْئًا غَیْرَ تَمْرَۃٍ وَاحِدَۃٍ فَاَعْطَیْتُھَا اِیَّاھَا فَاَخَذَتْھَا فَقَسَمَتْھَا بَیْنَ اِبْنَتَیْھَا وَلَمْ تَأْکُلْ مِنْہَا شَیْئًا ثُمَّ قَامَتْ فَخَرَجَتْ وَابْنَتَاہَا فَدَخَلَ عَلَیَّ النَّبِیُّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ فَحَدَّثْتُہٗ حَدِیْثَھَا فَقَالَ النَّبِیُّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ: مَنِ ابْتُلِیَ مِنَ الْبَنَاتِ بِشَیْئٍ فَاَحْسَنَ اِلَیْھِنَّ کُنَّ لَہ سِتْرًا مِّنَ النَّارِ ( صحیح مسلم،کتاب البر والصلۃ۔۔۔الخ،باب فضل الاحسان الی البنات، الحدیث:۲۶۲۹، ص۱۴۱۴)", "urdu": "حضور نبی صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم کی زو جہ مبارکہ حضرت بی بی عائشہ صدیقہ رضی اللّٰہ تعالیٰ عنہا نے فرمایا کہ میرے پاس ایک عورت اپنی دولڑکیوں کے ساتھ آئی اور مجھ سے کچھ مانگا تو میرے پاس اس نے ایک کھجور کے سوا کچھ نہیں پایا میں نے وہی کھجور اس کو دیدی تو اس نے اس کھجور کو اپنی دونوں لڑکیوں کے درمیان تقسیم کردیا اور خود اس میں سے کچھ بھی نہیں کھایاپھر وہ اُٹھی اور اپنی دونوں لڑکیوں کے ساتھ باہر چلی گئی۔ پھر جب میرے پاس نبی کریم صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم تشریف لائے تو میں نے حضور سے اس عورت کی بات بیان کردی تو حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا جو شخص بیٹیوں کے ساتھ مبتلا کیا گیا اور انکے ساتھ اچھا سلوک کیا تو یہ بیٹیاں اسکے لیے جہنم سے پردہ بن جائیں گی۔", "roman": "Huzoor Nabi Sallallahu Alayhi wa Sallam ki zauja-e-mubarakah Hazrat Bibi Aisha Siddiqah Radiyallahu Anha ne farmaya ke mere paas ek Aurat apni do Ladkiyon ke saath aayi aur mujh se kuch manga to mere paas us ne ek khajoor ke siwa kuch nahi paya main ne wahi khajoor us ko de di to us ne us khajoor ko apni dono Ladkiyon ke darmiyan taqseem kar diya aur khud us mein se kuch bhi nahi khaya phir woh uthi aur apni dono Ladkiyon ke saath bahar chali gayi. Phir jab mere paas Nabi Kareem Sallallahu Alayhi wa Sallam tashreef laye to main ne Huzoor se us Aurat ki baat bayan kar di to Huzoor Sallallahu Alayhi wa Sallam ne farmaya jo Shakhs betiyon ke saath mubtala kiya gaya aur un ke saath achha sulook kiya to yeh betiyan us ke liye Jahannam se Pardah ban jayengi."}, {"id": 6373, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 39, "arabic": "عَنْ زِیَادِ بْنِ عَلَاقَۃَ قَالَ: سَمِعْتُ جَرِیْرَ بْنَ عَبْدِ اللّٰہ یَقُوْلُ یَوْمَ مَاتَ الْمُغِیْرَۃُ بْنُ شُعْبَۃَ قَامَ فَحَمِدَ اللّٰہ وَاَثْنٰی عَلَیْہِ وَقَالَ: عَلَیْکُمْ بِاتِّقَائِ اللّٰہ وَحْدَہٗ لَا شَرِیْکَ لَہٗ وَالْوَقَارِ وَالسَّکِیْنَۃِ حَتّٰی یَاْتِیَکُمْ اَمِیْرٌ فَاِنَّمَا یَاْتِیْکُمْ الْآنَ ثُمَّ قَالَ: اِسْتَعْفُوْا لِاَمِیْرِکُمْ فَاِنَّہٗ کَانَ یُحِبُّ الْعَفْوَ ثُمَّ قَالَ: اَمَّا بَعْدُ فَاِنِّیْ اَتَیْتُ النَّبِیَّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ قُلْتُ: اُبَایِعُکَ عَلَی الْاِسْلَامِ فَشَرَطَ عَلَیَّ وَالنَّصْحِ لِکُلِّ مُسْلِمٍ فَبَایَعْتُہٗ عَلٰی ھٰذَا وَرَبِّ ھٰذَا الْمَسْجِدِ اِنِّیْ لَنَاصِحٌ لَکُمْ ثُمَّ اسْتَغْفَرَ وَنَزَلَ (صحیح البخاری،کتاب الایمان،باب قول النبی صلی اللّٰہ علیہ وسلم: الدین النصیحۃ۔۔۔الخ، الحدیث:۵۸،ج۱،ص۳۵)", "urdu": "زیاد بن عَلاقہ سے روایت ہے، انہوں نے کہا کہ میں نے حضرت جریر بن عبد اللّٰہ رضی اللّٰہ تعالیٰ عنہ سے سُناجس دن مُغِیْرہ بن شُعْبہ (حاکم کوفہ) کا وِصال ہوا تو وہ (خطبہ کے لیے) کھڑے ہوئے اور اللّٰہ کی حمد و ثناء کی اور فرمایا کہ تم لوگوں پر لازم ہے کہ اللّٰہ سے ڈرو جو وَحْدَہٗ لَاشَرِیْکَ لَہٗ ہے اور وقار و سکون کو لازم پکڑو یہاں تک کہ تمہارا دوسرا حاکم آجائے اور وہ اب آتا ہی ہے پھر کہا کہ اپنے سابق حاکم کے لیے مغفرت کی دعا کرو اس لیے کہ وہ بھی عفو ودر گزر کو پسند کرتے تھے ۔پھر فرمایا کہ جب میں حضور صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم کی خدمت میں (بیعت کے لیے) حاضر ہوا اور میں نے عرض کیاکہ میں اسلام پر بیعت کرتا ہوں تو آپ صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے اسلام کے ساتھ یہ شرط لگاکر کہ ہر مسلمان کی ’’خیر خواہی‘‘ کرنا مجھے بیعت فرمایاتو میں نے اس شرط پر آپ سے بیعت کرلی۔ مجھے اس مسجد کے رب کی قسم ہے کہ (اے کوفہ والو!) میں تمہارا خیرخواہ ہوں ۔پھر آپ نے مغفرت کی دعا مانگی اور منبر پر سے اُترگئے۔", "roman": "Ziyad bin Ilaqah se Riwayat hai, unhon ne kaha ke main ne Hazrat Jareer bin Abdullah RadiyAllahu Anhu se suna jis din Mugheerah bin Shu'bah (Haakim-e-Kufa) ka wisaal hua to woh (Khutbah ke liye) khade hue aur Allah ki hamd o sana ki aur farmaya ke tum logon par laazim hai ke Allah se daro jo Wahdahu La Shareeka Lahu hai aur waqar o sukoon ko laazim pakdo yahan tak ke tumhara doosra haakim aa jaye aur woh ab aata hi hai phir kaha ke apne saabiq haakim ke liye maghfirat ki Dua karo is liye ke woh bhi afw o darguzar ko pasand karte the. Phir farmaya ke jab main Huzoor Sallallahu Alayhi wa Sallam ki khidmat mein (bai'at ke liye) hazir hua aur main ne arz kiya ke main Islam par bai'at karta hoon to Aap Sallallahu Alayhi wa Sallam ne Islam ke saath yeh shart laga kar ke har Musalman ki 'khair-khwahi' karna mujhe bai'at farmaya to main ne is shart par Aap se bai'at kar li. Mujhe is Masjid ke Rab ki qasam hai ke (aye Kufa walo!) main tumhara khair-khwah hoon. Phir Aap ne maghfirat ki Dua maangi aur Mimbar par se utar gaye."}, {"id": 6374, "bookId": 10, "bookName": "منتخب حدیثیں", "volId": 11, "chapterId": 0, "chapterTitle": "", "hadithNo": 40, "arabic": "عَنْ اَبِیْ ھُرَیْرَۃَ رَضِیَ اللّٰہ تَعَالٰی عَنْہٗ قَالَ: قَالَ النَّبِیُّ صَلَّی اللّٰہ عَلَیْہِ وَسَلَّمَ: کَلِمَتَانِ حَبِیْبَتَانِ اِلَی الرَّحْمٰنِ خَفِیْفَتَانِ عَلَی اللِّسَانِ ثَقِیْلَتَانِ فِی الْمِیْزَانِ سُبْحَانَ اللّٰہ وَبِحَمْدِہٖ سُبْحَانَ اللّٰہ الْعَظِیْمِ (صحیح البخاری،کتاب التوحید،باب قول اللّٰہ عالٰی:ونضع الموازین القسط۔۔۔الخ، الحدیث:۷۵۶۳،ج۴،ص۶۰۰)", "urdu": "حضرت ابو ہریر ہ رضی اللّٰہ تعالیٰ عنہ راوی ہیں انہوں نے کہا کہ نبی صَلَّی اللّٰہ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا ہے کہ دو کلمے رحمن کو بہت زیادہ محبوب ہیں یہ زبان پر بہت ہی ہلکے اور میزانِ عمل میں بہت ہی بھاری ہیں (وہ دو کلمے یہ ہیں ) \n ’’ سُبْحَانَ اللّٰہ وَبِحَمْدِہٖ سُبْحَانَ اللّٰہ الْعَظِیْمِ ‘‘", "roman": "Hazrat Abu Hurairah RadiyAllahu Anhu Raawi hain unhon ne kaha ke Nabi Sallallahu Alayhi wa Sallam ne farmaya hai ke do kalme Rehman ko bahut zyada mehboob hain yeh zuban par bahut hi halke aur Meezan-e-Amal mein bahut hi bhaari hain (woh do kalme yeh hain)\n'Subhan Allahi wa bihamdihi Subhan Allahil Azeem'."}];
